INSERT INTO player_evaluations VALUES(1,1,1,'A — 상위 4경기 평균 7.95(rate_v, 풀 내 평점 백분위 91)로 GK 슬롯 확정 주전(obs#110 XI, prescriptions fc26:opt:GK starter). 실측 히트맵은 순수 골라인형(GK 커널 코사인 .96 vs 스위퍼 .63)이고 스위핑은 상황부라는 duties 판정과 일치. 최종 처방은 gk_ballplaying/Build-Up(2026-07-05 숙련도 타이브레이크 확정).','짧은 빌드업 개시 GK — 압박 아래에서도 풀백·CB 배급이 고정 원칙. 박스 폭 전체의 얕고 넓은 커버, 액션 볼륨 높음(한 경기 74+). 과잉 스위핑 증거 없음.','빌드업 관여+박스 장악, FC26 OVR 85(스쿼드 최고 GK)·PlayStyles 긴패스·돌진 블로킹. 약점: 오프라인 스위핑은 상시가 아니라 상황부 — 하이라인 배후 광역 커버를 요구하는 체제에는 실측 근거가 없다.','v_player_profile n=4, 평균 평점 7.95(풀 백분위 91, 최상위권), 270분. kp 1.75/경기는 GK로서 배급 관여 흔적. xG·태클 0은 포지션상 정상.','HIGH — squad rate_v 7.95 실측에 더해 에메리 빌드업 축(manager_profiles buildup)이 GK의 빌드업 참여를 명시적으로 요구 — 임무와 실측 발자국의 정합이 duties에서 HIGH 판정.','HIGH — 알론소의 3-2-5 숏 빌드업(tac-tac-tac 리듬)도 볼 플레잉 GK를 전제하며 마르티네스의 배급 실측이 그대로 이식 가능 (교차 투영 — 실측 아님).','MEDIUM — 고압박·하이라인 체제는 배후 스위핑 GK를 요구하나 실측 발자국은 골라인 고정, 스위핑은 상황부에 그침 (교차 투영 — 실측 아님).','squad_entries GK(rate_v 7.95); prescriptions kind=optimal·role·measured:season(GK); player_duties GK; v_player_profile n=4; player_game_stats FC26(OVR85, 긴패스·돌진 블로킹); obs#14','v_player_profile n=4는 표본 부족이고 rate_v도 ''상위 4경기'' 선별 표본이라 상향 편향 가능. 알론소·이라올라 핏은 교차 투영(실측 아님). ⚠️ 2026-08-11 갱신: 이 평가는 재수집 이전 표본으로 썼다 — 실측 표본이 64경기로 늘었고(obs#150) 스탯·백분위·시즌 성적은 새 표본을 반영한다. 등급·전술핏 문장은 재검토 대상이다.','2026-08-11');
INSERT INTO player_evaluations VALUES(2,1,2,'A− — 확정 XI의 RB(obs#110, fc26:opt:RB starter). rate_v 7.65(상위 6경기, 피크 8.4). 처방은 fb_wingback/Balanced — att_wb/Support(.898)와 Δ.007 동률(노이즈 이내)이라 FC26 숙련·에메리 C2 비대칭(수비우선 풀백) 근거로 채택(prescriptions optimal). obs#147 영상 분석에서 처방 정합 확인.','윙어 출신 라이트백 — 터프 태클과 드라이브 전진 런의 공수 겸장. 실측상 폭 규율은 절대적(매 경기 y~15-20, 절대 안쪽으로 안 들어옴)이고 높이는 게임플랜별 가변.','우측 터치라인 봉쇄와 전장 우측 커버(measured 코사인 .94가 att_wb 패턴), FC26 긴스로우 PlayStyle. 약점: 전진성은 C2 제약으로 구조가 봉인 — 인버티드 움직임 실측 전무.','v_player_profile n=53(4188분), 평균 평점 6.81(풀 백분위 35), xA 0.057/경기(백분위 47) — 수비 우선 임무 감안 시 공격 산출이 낮은 것은 역할 정합. 태클 2.0은 n=1 표본이라 인용 유보.','HIGH — obs#110 확정 XI RB이며 ''풀백 한 명씩만 전진'' C2 규칙의 잔류측 담당(manager_profiles implementation ④). duties 판정 HIGH.','MEDIUM — 3-4-2-1 윙백의 폭 독점 역할과 전장 우측 커버 실측(.94)은 맞닿으나, 공격 산출(xA 백분위 47)이 폭 공급자 기준으로는 평범 (교차 투영 — 실측 아님).','LOW — 이라올라의 인버티드 RB 성향(프림퐁 실측)과 정반대 — 캐시는 실측상 절대 안쪽으로 들어오지 않는 순수 와이드형 (교차 투영 — 실측 아님).','squad_entries FB(rate_v 7.65); prescriptions optimal·role·measured:season(RB); player_duties RB 2행; v_player_profile n=53; FC26(OVR81, 긴스로우); obs#110·#147','n=53으로 표본 충분. 단 태클·인터셉트는 지표별 표본 n=1로 희박. 알론소·이라올라 핏은 교차 투영(실측 아님).','2026-08-11');
INSERT INTO player_evaluations VALUES(3,1,3,'S− — RCB 43경기 평균 7.05(rate_v), 시즌 그리드 cb_bpd/Aggressive 코사인 .938(role:season, 2위 Build-Up .865)로 스쿼드에서 가장 강한 역할 실측 정합. 패스 96%로 스쿼드 최고(duties 이벤트 스탯) — BPD 3축 충족으로 cb_bpd 승급. 확정 XI RCB(obs#110).','태클 대신 포지셔닝·요격으로 수비하는 passive-aggressive형. 우측 듀얼·공중볼 앵커이면서 소유 시 볼을 들고 우중앙 미드필드로 스텝업 — 스텝아웃 캐리는 서사가 아니라 실측(duties).','스텝아웃 캐리+패스 96%의 볼 플레잉, FC26 OVR 84·PlayStyles 예상+·견제·슬라이딩태클. 약점: 공중볼·크로스 대응(영상 분석, duties) — 게임 공중볼 스탯도 낮아 세트피스 마킹 주의.','v_player_profile n=48(4170분), 평균 평점 7.05(풀 백분위 56), xG 0.193(백분위 52 — CB로는 세트피스 위협 반영). 태클·인터셉트는 지표 표본 n=0(결측)이라 인용하지 않음.','HIGH — role:season .938은 스쿼드 최상위 실측 적합. 에메리 백라인 스텝아웃·볼 플레잉 요구(obs#22 — CB Defender 숙련을 BPD로 기용)와 정확히 일치.','HIGH — 알론소는 전 CB cb_bpd/Aggressive를 요구(implementation ①)하며 콘사의 실측 커널이 정확히 그 역할 — 백3 우측 스토퍼로 직이식 가능 (교차 투영 — 실측 아님).','MEDIUM — 하이라인 배후 커버는 pac 75와 요격형 수비(예상+)로 감당 가능하나 전면 맨투맨 전환 체제의 1v1 노출은 실측 검증 없음 (교차 투영 — 실측 아님).','squad_entries CB(rate_v 7.05); prescriptions optimal·role·role:season·measured@dom/@tight(RCB); player_duties RCB 2행; v_player_profile n=48; FC26(OVR84); obs#110·#147','n=48로 표본 충분, 실측 신뢰 높음. 태클·인터셉트 지표는 표본 0. 알론소·이라올라 핏은 교차 투영(실측 아님).','2026-08-11');
INSERT INTO player_evaluations VALUES(4,1,4,'A — 상위 5경기 평균 7.35(rate_v), cb_bpd/Build-Up ''명백히 확인''(duties·prescriptions optimal — 기능 pass 88% 진전형, 움직임 Aggressive .65 vs Build-Up .63은 노이즈차). 좌중앙 채널을 올라가며 전진하는 교과서적 좌측 볼 플레잉 CB. 확정 XI LCB(obs#110).','좌측 볼 플레잉 CB — 캐리·패스로 좌 하프스페이스 전진, 인버티드 좌측 공격에 공급. 실측상 y~67-71 좌중앙 상수, 깊이는 지배도에 비례. 오픈플레이 공격 3분의1 볼륨은 0에 가까움(전진은 빌드업 국면 한정).','좌 하프스페이스 전진 배급, FC26 핑패스 PlayStyle·pas 75. 약점: pac 67·sho 41 — 회복 속도가 낮아 하이라인 배후 커버와 뒷공간 노출에 취약.','v_player_profile n=6, 평균 평점 7.2(풀 백분위 70), 듀얼승 4.33(백분위 81)·태클 1.5(백분위 68). 단 n=6으로 표본 부족 — 백분위 과신 금지. 낮은 xA(백분위 13)는 CB 포지션상 정상.','HIGH — 확정 XI LCB이며 빌드업 축(볼플레잉 CB 2인, obs#16)의 좌측 담당. duties 판정 HIGH.','HIGH — 백3 전원 cb_bpd 요구 체제에 좌측 BPD로 직결. 다만 알론소 처방은 Aggressive 포커스라 Build-Up 성향과 미세 긴장 (교차 투영 — 실측 아님).','LOW — pac 67로 하이라인+전면 맨투맨 전환 체제의 배후 공간 리스크가 큼 (교차 투영 — 실측 아님).','squad_entries CB(rate_v 7.35); prescriptions optimal·role·measured:season(LCB); player_duties LCB; v_player_profile n=6; FC26(OVR80, 핑패스); obs#89·#110','v_player_profile n=6은 표본 부족 — 백분위 서술은 참고 수준. 알론소·이라올라 핏은 교차 투영(실측 아님). ⚠️ 2026-08-11 갱신: 이 평가는 재수집 이전 표본으로 썼다 — 실측 표본이 57경기로 늘었고(obs#150) 스탯·백분위·시즌 성적은 새 표본을 반영한다. 등급·전술핏 문장은 재검토 대상이다.','2026-08-11');
INSERT INTO player_evaluations VALUES(5,1,6,'B+ — 확정 XI LB(obs#110)이나 rate_v 6.74(LB 16경기)로 XI 중 가장 낮은 축. 측정된 수비수 중 가장 전진형 발자국(평균 높이 44-56/100)이면서 홈/원정 요동이 스쿼드 최대(홈 ~51.6 vs 원정 ~43.6) — 하이앤와이드는 주로 홈 현상이고 원정에선 딥으로 수렴(duties 보강 실측).','공격형 레프트백 — 높고 넓은 시작 위치에서 좌 하프스페이스로 바이라인까지 침투, 좌측 채널 엔드투엔드 왕복(브렌트포드전 115히트·100터치·6태클). 시즌 그리드 최적은 fb_wingback/Balanced .862(role:season — 베스트게임 att_wb 표본의 공격 편향 교정).','pac 87·래피드 PlayStyle의 왕복 볼륨과 좌측 오버로드 창출(xA 0.242, 풀 백분위 87). 약점: 평균 평점 6.63(백분위 18)으로 산출 일관성 낮음 — 원정·강한 윙어 상대면 평범한 딥 LB로 붕괴(duties), 그땐 Defend 변형 권고.','v_player_profile n=45(2437분), 평균 평점 6.63(풀 백분위 18 — 하위권), xA 0.242(백분위 87)·키패스 1.6(백분위 70)으로 창출 지표는 상위. 평점과 창출의 괴리가 프로필의 핵심.','HIGH — 확정 XI LB로 C2 비대칭의 전진측(fb_att_wb 변형) 담당. 단 홈/지배 임무 한정 HIGH이며 원정 변형에선 Balanced/Defend 강등이 처방(duties).','HIGH — 알론소 좌 윙백은 인선 공백(formation 축)이고 마첸의 하이앤와이드 실측 프로필이 윙백 폭 독점 요구에 부합 (교차 투영 — 실측 아님).','MEDIUM — 고강도 왕복과 pac 87은 부합하나 홈/원정 요동과 낮은 평점 일관성이 고압박 체제의 상시 강도 요구와 긴장 (교차 투영 — 실측 아님).','squad_entries FB(rate_v 6.74); prescriptions optimal·role:season·measured@dom/@tight(LB); player_duties LB; v_player_profile n=45; FC26(OVR79 POT84, 슬라이딩태클·래피드); obs#95·#110·#128','n=45로 표본 충분. 홈/원정 분리 실측이 있어 맥락 신뢰 높음. 알론소·이라올라 핏은 교차 투영(실측 아님). ⚠️ 2026-08-11 갱신: 이 평가는 재수집 이전 표본으로 썼다 — 실측 표본이 60경기로 늘었고(obs#150) 스탯·백분위·시즌 성적은 새 표본을 반영한다. 등급·전술핏 문장은 재검토 대상이다.','2026-08-11');
INSERT INTO player_evaluations VALUES(6,1,7,'B — 백업 CB, 상위 4경기 평균 7.05(rate_v)에 양쪽 CB 커버 가능. 시즌 그리드 cb_bpd/Aggressive .826 >> Build-Up .741로 스텝아웃 뚜렷(prescriptions optimal LCB). obs#14 전 스쿼드 재검증에서 유일하게 처방이 교정된 사례.','양쪽 CB을 모두 커버하는 로테이션 자원. 실측상 스텝아웃 성향의 BPD형 — RCB·LCB·RDM 세 슬롯에 처방 이력.','좌우 겸용 유연성과 스텝아웃 빌드업(.826). 약점: pac 50(풀백업 중 최저 수준)·OVR 76 — 하이라인·회복 수비 상황 취약, FC26 PlayStyles 없음.','v_player_profile n=5, 평균 평점 6.88(풀 백분위 39). 표본 부족으로 지표 백분위 전반 인용 유보 — 듀얼승 1.0(백분위 11)도 n=5 기반.','MEDIUM — 로테이션 CB로 처방 정합(.826)은 확인됐으나 XI 밖. 표본 3~5경기라 기능축 근거 약함(prescriptions optimal 주석).','MEDIUM — 백3 체제는 BPD CB 수요가 3장이라 로테이션 가치가 오히려 커질 수 있으나 Aggressive 강도 요구 대비 기동력 의문 (교차 투영 — 실측 아님).','LOW — pac 50으로 하이라인·전면 맨투맨 체제 부적합 (교차 투영 — 실측 아님).','squad_entries CB(rate_v 7.05); prescriptions fc26:opt:LCB/RCB/RDM·optimal·measured:season; v_player_profile n=5; FC26(OVR76); obs#14 (player_duties 행 없음)','n=5 표본 부족 — 등급 과신 금지. player_duties 미작성 선수. 알론소·이라올라 핏은 교차 투영(실측 아님). ⚠️ 2026-08-11 갱신: 이 평가는 재수집 이전 표본으로 썼다 — 실측 표본이 66경기로 늘었고(obs#150) 스탯·백분위·시즌 성적은 새 표본을 반영한다. 등급·전술핏 문장은 재검토 대상이다.','2026-08-11');
INSERT INTO player_evaluations VALUES(7,1,8,'A− — 피벗 29경기 평균 7.13(rate_v), 확정 XI LDM(obs#110 starter). 처방은 dm_holding/Roaming(2026-07-05 숙련도 타이브레이크 확정) — 움직임은 dlp .87이나 기능은 볼위닝(태클 3.4·듀얼 6.6 스쿼드 최상위, 창조 최저 xa .04·kp 1.0, prescriptions optimal). 단 obs#129가 26/27 피봇을 ''카마라 RDM·고메스 LDM''으로 기록해 슬롯 경쟁 존재.','더블 피벗의 박스투박스·만능 어댑터 — 중앙/좌/우 세 레인 산출이 거의 동일(중앙 7.21/우 7.04/좌 7.05)하고 평점이 파트너 독립적. 공중볼 최강(195cm)·듀얼 머신, 슛의 35%가 헤더로 박스 존재감은 대부분 세트피스 도착(샷맵).','듀얼·공중·스크린+박스 쇄도, FC26 프리시전 헤딩·슬라이딩태클·압박검증·인포서 4종 PlayStyles. 약점: 창조성 최저(xa .04·kp 1.0) — 플레이메이커 역할 부적합이 기능 실측으로 확정.','v_player_profile n=38(2649분), 평균 평점 7.05(풀 백분위 56). xA 0.044(백분위 30)로 창조 하위 — 볼위닝 홀딩형 프로필과 정합. 태클·인터셉트 지표 표본 n=0이라 duties 이벤트 스탯(태클 3.4·듀얼 6.6)으로 대체 인용.','HIGH — 확정 XI LDM이고 더블 피벗 dm_holding 분담(implementation ②)의 볼위닝 축. 세 레인 만능성이 에메리 피벗 로테이션에 직결.','HIGH — 알론소 rest_defense 축이 ''더블피벗 중 한 명 Defend 계열 보험''을 명시적으로 요구 — 오나나의 볼위닝 홀딩 기능이 그 보험 그 자체 (교차 투영 — 실측 아님).','MEDIUM — 듀얼·압박검증은 부합하나 Controlled Lengthy 가속과 창조 최저 기능이 탈취 후 즉시 슛 전환 체제와 부분 긴장 (교차 투영 — 실측 아님).','squad_entries DM(rate_v 7.13); prescriptions optimal·role·role:season(LDM); player_duties pivot·LDM 2행; v_player_profile n=38; FC26(OVR81, PlayStyles 4종); obs#32·#110·#129·#145','n=38 충분. 단 XI LDM은 obs#110(2026-08-11)과 obs#129(고메스 LDM) 간 기록 긴장 존재 — 최신 확정은 obs#110. 알론소·이라올라 핏은 교차 투영(실측 아님).','2026-08-11');
INSERT INTO player_evaluations VALUES(8,1,10,'S — 주장이자 확정 XI RM(obs#110 starter). RM 21경기 7.08에 천장 경기 전부(8.7/8.6/8.5), 피벗우측 7경기 7.87(fit_sim .878 — 자체 실측 최고), CAM .801까지 3슬롯 실측 보유. obs#145에서 외부 영상 분석이 내부 실측(obs#27·#89)을 독립 재현한 ''검증자 사례''.','명목 우측이나 움직임은 내부·수직의 하이브리드 — 듀얼 5.75/90 스쿼드 최다, 찬스 창출 최다, 중거리 위협. 샷맵상 헤더 0·평균 17.1m — 박스 스트라이커가 아니라 박스 가장자리 인사이드 포워드형 도착.','뱅크 복귀(wm_widemid/Support)와 하프스페이스 런의 겸장, 압박검증·끈기와인내·인포서 PlayStyles. 험지 원정에선 피벗우측 강등이 오히려 평점 상승(7.30). 약점: 피로 누적 시 수행 저하(영상 분석 캐비앗)와 FC26 ''부상에 취약함'' 트레잇, CAM 기용은 부가가치 없음(duties MEDIUM).','v_player_profile n=44(3039분), 평균 평점 7.01(풀 백분위 54), xG 0.212(백분위 57)·xA 0.107(백분위 60)·키패스 1.38(백분위 65) — 공격 관여 전 지표가 풀 중상위.','HIGH — fit_sim 실측 .878(DM)·.801(CAM)에 확정 XI RM. 에메리 두 줄 4의 우측 뱅크 복귀 역할(implementation ②)을 정의하는 선수.','MEDIUM — 2×10번 하프스페이스 포켓에 인사이드 포워드 도착 성향이 닿으나 알론소 10번은 창조 우선(팔머형) — 맥긴은 듀얼·수직형 (교차 투영 — 실측 아님).','HIGH — 듀얼 최다·압박검증·수직 움직임이 고강도 압박과 측면 압축 체제에 직결 — 단 피로 민감성은 강행군 리스크 (교차 투영 — 실측 아님).','squad_entries CAM/DM/WM 3행(fit_sim .801/.878); prescriptions optimal·role·role:season(RM)·measured:CAM/pivot-right; player_duties RM·pivot-right·CAM·RM(영상) 4행; v_player_profile n=44; FC26(OVR81); obs#110·#145','n=44 충분, 3슬롯 실측이 모두 존재해 신뢰 최상급. CAM fit_sim은 n=4 소표본. 알론소·이라올라 핏은 교차 투영(실측 아님).','2026-08-11');
INSERT INTO player_evaluations VALUES(9,1,11,'B− — 다슬롯 백업(RDM·RB). 피벗 21경기 6.62, RB 8선발 704분 6.46(fit_sim .832 — obs#99가 ''n=1'' 오류를 8선발 전수로 교정, obs#104에서 포커스 Balanced 확정). 처방 dm_holding/Ball-Winning 벤치 — 카마라와 동형 볼위닝 홀딩(prescriptions optimal RDM).','볼위닝형 유틸리티 — 듀얼 5.8·인터셉트 1.8, 창조 xa .03(prescriptions optimal 기재). 시즌 실측 그리드는 명백히 우측(RDM x=62), CDM/CM/RB 겸업.','피벗과 RB를 모두 메우는 커버 폭, POT 81의 성장 여지. 약점: 평균 평점 6.63(풀 백분위 18)·xA 백분위 17 — 산출 전반이 하위권, OVR 74로 게임 즉전력도 낮음.','v_player_profile n=44(2140분), 평균 평점 6.63(풀 백분위 18). xA 0.027(백분위 17)로 창조 최하위권 — 볼위닝 백업이라는 처방과 정합. 태클·인터셉트 지표 표본 n=0.','MEDIUM — 벤치 처방이 실측으로 정리된 백업. RDM(볼위닝 홀딩)과 RB(fb_wingback/Balanced .832) 두 슬롯 실측 보유가 가치.','LOW — 박스 미드필드의 극단적 기술 규율 요구(rest_defense 축) 대비 창조·배급 산출이 하위권 (교차 투영 — 실측 아님).','MEDIUM — 젊은 볼위너로 압박 체제 원자재는 되나 실측 근거는 에메리 체제뿐 (교차 투영 — 실측 아님).','squad_entries DM/FB 2행(fit_sim .832); prescriptions optimal(RDM)·measured:season·role:season; v_player_profile n=44; FC26(OVR74 POT81); obs#99·#104 (player_duties 행 없음)','경기수 n=44이나 슬롯별로 쪼개면 RB 8선발 등 소표본. player_duties 미작성. 알론소·이라올라 핏은 교차 투영(실측 아님). ⚠️ 2026-08-11 갱신: 이 평가는 재수집 이전 표본으로 썼다 — 실측 표본이 63경기로 늘었고(obs#150) 스탯·백분위·시즌 성적은 새 표본을 반영한다. 등급·전술핏 문장은 재검토 대상이다.','2026-08-11');
INSERT INTO player_evaluations VALUES(10,1,12,'S — 확정 XI RDM(obs#110 starter)이자 3선 배급 주도자(obs#129). 피벗 16경기 7.14(rate_v). 움직임 코사인은 dm_dlp/Roaming .83이 최고지만 기능 실측이 스쿼드 1위 볼위닝(듀얼승 8.4, 창조 최저 xA .04·KP 1.0)이라 dm_holding/Ball-Winning으로 확정(2026-07-05 A/B 종결) — ''움직임=dlp, 기능=holding'' 하이브리드.','우중앙 딥라잉 플레이메이커처럼 움직이는 볼위닝 앵커 — ''깊이 앉는 앵커'' 서사는 탈편향 표본으로 기각(duties). 짧은 연결과 프레스 위 클리핑 롱패스 겸장, 영상 분석상 유의미 약점 없음(obs#147 정합).','볼위닝+빌드업 겸장(패스량 56/경기·87%), FC26 OVR 84·POT 86으로 필드 최고 등급. 약점: 창조 산출 최저(xA 백분위 27) — 창조 역할 배치 금지가 제약으로 관리됨(obs#130 FUNC_AXIS).','v_player_profile n=27(1768분), 평균 평점 7.07(풀 백분위 60), 듀얼승 8.0(백분위 91 — 단 지표 표본 n=1). 인터셉트 ''3.0 vs 1.40'' 불일치는 지표별 표본 수 차이로 규명됨(obs#131) — 수치 인용 시 주의.','HIGH — 확정 XI RDM, 더블 피벗 dm_holding 분담의 핵. 11연승 기간 우측 고정 실측(duties)이 체제 기여를 직접 증명.','HIGH — 알론소 카이세도 하강 피벗(dm_dlp/Roaming, 백라인 옆 압박 유인)과 카마라의 dlp형 움직임 실측(.83)이 동형 (교차 투영 — 실측 아님).','MEDIUM — 볼위닝·커버 범위는 부합하나 pac 64·Controlled Lengthy가 수직 전환 최속 체제(1.95m/s)와 긴장 (교차 투영 — 실측 아님).','squad_entries DM(rate_v 7.14); prescriptions optimal·role·role:season(RDM); player_duties LDM·RDM 2행; v_player_profile n=27; FC26(OVR84 POT86, 블로킹); obs#110·#129·#130·#131·#132·#147','n=27 충분하나 듀얼·인터셉트 지표는 표본 1~2경기 — obs#131이 지적한 지표별 표본 불일치 상존. 알론소·이라올라 핏은 교차 투영(실측 아님).','2026-08-11');
INSERT INTO player_evaluations VALUES(11,1,14,'A− — 확정 XI LM(obs#110, fc26:opt:LM starter). 좌측 와이드 21경기 6.90에 천장이 압도적(피크 9.4 포레스트 4강·8.5 본머스·8.3 EL 결승 — 전부 좌중앙 실측). CAM fit_sim .672는 n=3 소표본이라 판단 근거로 약함. ''우측 드리프트 10번'' 언론 서사는 실측으로 기각(시즌 우측 선발 2회뿐).','윙어가 아니라 좌편향 자유 플레이메이커 — 라인 사이 수신, 인필드 이동 후 중거리 드리븐, 크로스 적음(duties 영상 종합, obs#145 정합). 4-4-2 블록에선 세컨드 스트라이커로 압박. 절대 우측 배치 금지(duties).','녹아웃·빅매치 천장과 키패스 1.93(풀 백분위 74)·xG 백분위 74·xA 백분위 70의 창조 프로필, FC26 테크니컬·슬라이딩태클. 약점: 리그 시즌 일관성 보통(duties) — 평균 평점 6.93(백분위 47)이 천장 대비 낮음.','v_player_profile n=55(2988분), 평균 평점 6.93(풀 백분위 47), xG 0.316(백분위 74)·xA 0.189(백분위 70)·키패스 1.93(백분위 74) — 창출 지표 일괄 상위. 듀얼·태클 백분위 98은 지표 표본 n=1이라 인용 유보.','HIGH — 확정 XI LM이며 에메리 ''자유 10번 로밍''(traits 축)의 좌편향 담당. cam_playmaker/Roaming 처방이 duties·영상·실측 3축 정합.','HIGH — 2×10번 하프스페이스 체제의 좌측 포켓에 라인 사이 수신·창조 프로필이 직결 (교차 투영 — 실측 아님).','MEDIUM — 세컨드 스트라이커 압박 실측은 있으나 고강도 왕복의 상시 요구와 리그 일관성 저하가 긴장 (교차 투영 — 실측 아님).','squad_entries CAM/WM 2행(fit_sim .672 n=3); prescriptions optimal(LW)·role·role:LM·measured 다수; player_duties LW/left-10·pivot-left·CAM 3행; v_player_profile n=55; FC26(OVR78); obs#110·#124·#127·#145','n=55 충분. 단 CAM fit_sim은 n=3 표본 부족 — CAM 슬롯 판단엔 쓰지 말 것. 알론소·이라올라 핏은 교차 투영(실측 아님).','2026-08-11');
INSERT INTO player_evaluations VALUES(12,1,15,'B− — 벤치 인버티드 RW(prescriptions optimal ''[bench] Left-footed inverted RW'', 상위 경기 7.5/7.4/7.1). rate_v 7.33이나 v_player_profile n=3으로 표본 부족 — 등급 판단 자체가 잠정. obs#134가 지목한 ''실제 공백은 우측 와이드'' 맥락에서 조건부 옵션.','왼발 컷인형 인버티드 우측 와이드. FC26 수집값 기준 PlayStyles 감아차기·트릭스터, dri 86의 온더볼 유형.','드리블 86·컷인 슈팅 각 창출. 약점: def 35·phy 54로 수비 관여 최저 수준 — 두 줄 4 뱅크 복귀 임무와 구조적 긴장, 가속 데이터 결측.','v_player_profile n=3(226분) — 표본 부족. 평균 평점 7.33(백분위 81)·xA 0.3(백분위 93)은 3경기 기반이라 백분위 인용은 참고 수준을 넘지 말 것.','MEDIUM — 상위 경기 실측은 좋으나 표본 3경기뿐이고, 뱅크 복귀형 우측(wm_widemid/Support)이 기본인 체제에서 수비 관여 최저 프로필은 조건부.','MEDIUM — 하프스페이스 10번 포켓 변환 여지는 있으나 극단적 기술 규율·수비 전환 요구와 def 35의 긴장 (교차 투영 — 실측 아님).','LOW — 고강도 압박·왕복 체제에 수비 스탯 최저 프로필 (교차 투영 — 실측 아님).','squad_entries WM(rate_v 7.33); prescriptions optimal(RW)·measured:season; v_player_profile n=3; FC26(OVR79, 감아차기·트릭스터 — 2026-06-30 수집값); obs#30·#84 (player_duties 행 없음)','n=3 표본 부족 — 모든 수치 캐비앗, 등급 과신 금지. player_duties 미작성. 알론소·이라올라 핏은 교차 투영(실측 아님). ⚠️ 2026-08-11 갱신: 이 평가는 재수집 이전 표본으로 썼다 — 실측 표본이 48경기로 늘었고(obs#150) 스탯·백분위·시즌 성적은 새 표본을 반영한다. 등급·전술핏 문장은 재검토 대상이다.','2026-08-11');
INSERT INTO player_evaluations VALUES(13,1,16,'S — 체제의 원톱. 상위 7경기 평균 8.47(rate_v, 스쿼드 최고)에 xG 1.327/경기는 풀 백분위 96. st_advanced/Versatile 확정 — ''박스 점유/링크/채널 런'' 3중 임무가 경기 유형별로 깨끗이 분리되면서 득점 산출은 상수(3경기 각 2골, duties). 실측·영상·처방 3축 강정합(obs#145).','뒷공간 런 리그 1위의 박스 상주형(채널 러너에서 진화). 샷맵: 103슛 중 박스 내 84%·6야드 24·헤더 19, xG/슛 0.19 — 순수 박스 도착 프로필. 양발+헤더 마무리, 전방 압박 탈취.','임무 순응성(시스템에서 가장 게임플랜 순응적인 공격수)과 엘리트 피니시, FC26 칩슛·프리시전 헤딩·끈기와인내. 약점: 창조 안 함(xA 0.03, duties) — Support(링크형) 포커스 부적합 판정, FC26 ''부상에 취약함'' 트레잇.','v_player_profile n=56(3917분), xG 1.327/경기(풀 백분위 96 — 단 xG 지표 표본 n=3 캐비앗), 키패스 2.0(백분위 76). 평균 평점 6.85(백분위 37)는 ST 평점 체계 특성 감안 — rate_v 상위 표본과의 괴리는 선별 기준 차이.','HIGH — 확정 XI ST(obs#110 starter). 원톱 3중 임무의 실측 정합이 duties에서 교과서 사례로 기록됨.','MEDIUM — 알론소 9번은 내려오는 false9(st_false9/Build-Up) — 왓킨스는 박스 점유·인비하인드형이라 역할 정의가 어긋남 (교차 투영 — 실측 아님).','HIGH — 뒷공간 런 리그 1위·전방 압박 탈취가 수직 전환+파이널서드 탈취 체제와 직결 (교차 투영 — 실측 아님).','squad_entries ST(rate_v 8.47); prescriptions optimal·role·measured:season(ST); player_duties ST 2행(샷맵 포함); v_player_profile n=56; FC26(OVR82); obs#110·#145','n=56 충분. 단 xG 백분위 96은 지표 표본 n=3 기반 — 방향은 확실하나 크기는 과신 금지. 알론소·이라올라 핏은 교차 투영(실측 아님). ⚠️ 2026-08-11 갱신: 이 평가는 재수집 이전 표본으로 썼다 — 실측 표본이 71경기로 늘었고(obs#150) 스탯·백분위·시즌 성적은 새 표본을 반영한다. 등급·전술핏 문장은 재검토 대상이다.','2026-08-11');
INSERT INTO player_evaluations VALUES(14,1,55,'A− — 합류 확정, obs#110 확정 XI의 CAM(fc26:opt:CAM starter). CAM 적합 .861(cam_halfwinger/Balanced, 대표팀 12경기 7.2), DM .713(클럽 56경기 7.2). obs#138: 클럽(프라이부르크)과 대표팀은 서로 다른 선수 — 클럽은 좌측·후방 박스투박스, 대표팀·월드컵은 전방·우측 10번. obs#148 고메스와 클럽 그리드 코사인 .960 — 사용자 확정 방침대로 CAM 기용이 역할 분담 해법.','캐리로 전진하는 박스투박스 — 드리블 돌파보다 운반, 박스 침투 시 공중볼 위협, 중거리 슈팅(영상 종합 가설, obs#142 파일럿). 수비 기여 실재(태클 1.52·탈취 4.69/90, duties).','60경기 전수 실측의 큰 표본과 이중 프로필(10번/8번), FC26 POT 86(스쿼드 최고 성장폭)·테크니컬. 약점: 온더볼 캐리 전진은 그리드 밖이라 미검증, 빌라 실측 0경기.','v_player_profile n=59(4057분), 평균 평점 7.2(풀 백분위 70), 듀얼승 6.02(백분위 85)·인터셉트 0.83(백분위 74) — 공수 겸장 프로필이 백분위로 확인. xG 0.174(백분위 43)는 10번 기준 평범.','HIGH — fit_sim .861은 실측 기반이며 에메리 ''자유 10번'' 슬롯의 cam_halfwinger 처방(implementation ⑤)과 정합. 단 전방 프로필은 대표팀 실측(n=12)이 근거.','HIGH — 하프윙어 10번 프로필이 2×10번 하프스페이스 체제에 직결, 수비 기여도 rest_defense 리스크 완화 (교차 투영 — 실측 아님).','MEDIUM — 왕복·듀얼 볼륨은 부합하나 전방 압박 트리거 수행은 미검증 (교차 투영 — 실측 아님).','squad_entries CAM/DM 2행(fit_sim .861/.713); prescriptions fc26:opt:CAM(starter)·measured 대회별 7행; player_duties LDM; v_player_profile n=59; FC26(OVR77 POT86, 테크니컬); obs#138·#142·#148','n=59 충분하나 CAM 근거는 대표팀 n=12 축 — 클럽 표본과 프로필이 갈리는 이중성 캐비앗. 빌라 실측 0경기. 알론소·이라올라 핏은 교차 투영(실측 아님).','2026-08-11');
INSERT INTO player_evaluations VALUES(15,1,56,'A− — 합류 확정 피벗. DM fit_sim .763(dm_dlp/Roaming, 39경기 6.77). obs#143 파일럿의 첫 실질 수확: 서사(볼위닝 destroyer)와 위치 실측(dlp)의 긴장 — obs#144 재검토로 dm_dlp/Roaming 유지 종결(holding계 최고 .679). obs#129 기준 26/27 LDM 배치·볼위닝 담당(배급 주도는 카마라).','볼위닝 destroyer + 박스 침투(''6과 절반''), 프레스 저항 캐리(영상 종합 가설). 실측 수비 지표가 풀 최상위 — 기능은 볼위너, 움직임은 dlp인 하이브리드.','태클 3.0(풀 백분위 87)·듀얼승 6.35(백분위 89)·인터셉트 1.02(백분위 85)의 수비 삼종 최상위, FC26 슬라이딩태클·압박검증. 약점: 창의성(영상 분석 명시) — xG 백분위 13, 평균 평점 6.8(백분위 30)로 산출 낮음.','v_player_profile n=40(3268분), 평균 평점 6.8(풀 백분위 30). 수비 지표(태클 87·듀얼 89·인터셉트 85 백분위)는 전 지표 표본 n=40·34로 신뢰 — 풀 내 최고 수준 볼위너 프로필.','HIGH — fit_sim .763 실측에 obs#129 피봇 배치 확정. 만잠비와의 코사인 .960 중복은 CAM/LDM 분담으로 해소(obs#148).','MEDIUM — rest_defense 보험형 볼위너로는 최적이나 3선 배급·기술 규율 요구 대비 창조 최하위 (교차 투영 — 실측 아님).','HIGH — 프레스 저항 캐리+풀 최상위 태클·듀얼이 고강도 압박·즉시 탈취 체제에 직결 (교차 투영 — 실측 아님).','squad_entries DM(fit_sim .763); prescriptions measured(LDM n=39)·fc26:opt:LDM/RDM; player_duties LDM; v_player_profile n=40; FC26(OVR78 POT83); obs#129·#143·#144·#148','n=40 충분(울버햄튼 25/26 실측 — 에메리 체제 아님, 이적 후 재검증 필요). 알론소·이라올라 핏은 교차 투영(실측 아님).','2026-08-11');
INSERT INTO player_evaluations VALUES(16,1,57,'B+ — 합류 확정 CB. fit_sim .883(cb_bpd/Aggressive, 29경기 7.1)으로 실측 적합은 주전급이나 FC26 OVR 68로 게임 즉전력은 백업 — POT 81 성장형 영입. obs#143 파일럿에서 처방 정합 확인.','공중 지배(191cm)·후방 빌드업 개시·세트피스 골위협, CB/DM 겸업 가능(영상 종합 가설 — DM 겸업은 실측 표본 생기면 검증, duties).','공중볼과 스텝아웃 빌드업의 겸장, 듀얼승 4.1(풀 백분위 77)·인터셉트 0.86(백분위 77). 약점: FC26 능력치 전반 낮음(pas 53·dri 53) — 실측 프로필과 게임 스탯의 괴리가 스쿼드 내 최대.','v_player_profile n=29(2571분), 평균 평점 7.1(풀 백분위 63), 듀얼승·인터셉트 백분위 77로 수비 지표 상위. 낮은 xG 백분위(39)는 CB 포지션상 정상 — 오히려 0.16/경기는 세트피스 위협 흔적.','HIGH — fit_sim .883은 콘사(.938)에 이은 CB 실측 적합 상위. 단 즉시 XI가 아니라 성장 후 승계 트랙 (오스트리아 LASK 실측 — 에메리 체제 아님).','HIGH — cb_bpd/Aggressive 전원 요구 체제와 커널이 정확히 동형 (교차 투영 — 실측 아님).','MEDIUM — 공중·요격형은 유용하나 pac 69와 하이라인 1v1 노출 미검증 (교차 투영 — 실측 아님).','squad_entries CB(fit_sim .883); prescriptions measured(RCB n=29)·fc26:opt:LCB/RCB; player_duties RCB; v_player_profile n=29; FC26(OVR68 POT81); obs#143','n=29 충분하나 하위 리그(LASK) 실측 — PL 강도 미검증. FC26 스탯과 실측의 괴리 큼. 알론소·이라올라 핏은 교차 투영(실측 아님).','2026-08-11');
INSERT INTO player_evaluations VALUES(17,1,58,'A− — 합류 확정 윙어. W 슬롯 fit_sim .936(w_winger/Versatile — 단 첼시 25/26 실측 6경기, 규칙 7상 출처 명기)·WM .771(wm_winger/Attack, 38경기 6.99). obs#143: 컷인형 윙어 서사와 커널 정합. obs#125·#134 맥락에서 좌측 윙어 기용 시 LB 처방 연쇄 변경 필요(obs#128).','컷인 후 파포스트 감아차기, 1v1 돌파·볼캐리, 카운터 위협 — 좌 편향(좌측 38경기). PlayStyles는 감아차기·아크로바틱·테크니컬·퀵스텝(2026-07-23 수집값 — 종전 ''트릭스터'' 기재는 2026-08-11 교정된 허위, duties 명기).','pac 86·Mostly Explosive의 순간 가속과 컷인 슈팅, POT 84. 약점: def 37·phy 56 — 두 줄 4 뱅크 복귀 임무와 구조적 긴장(obs#125의 wm_winger 포커스 논의 대상).','v_player_profile n=38(2131분), 평균 평점 6.99(풀 백분위 51), xG 0.225(백분위 61)·xA 0.137(백분위 63) — 공격 산출 중상위, 수비 지표(듀얼 백분위 34·태클 38)는 하위.','HIGH — WM .771 실측 + XI 후보(fc26:opt:LM/RM). 단 .936은 첼시 25/26 출처 실측이라 에메리 체제 근거로는 .771이 1차.','MEDIUM — 첼시 실측 .936이 있으나 그것은 25/26 전임 체제 기록(규칙 7)이고, 알론소 3-4-2-1엔 순수 윙어 슬롯이 없어 10번 포켓 변환이 전제 (교차 투영 — 실측 아님).','HIGH — 1v1 돌파·카운터 위협·pac 86이 수직 전환 체제의 이상형 — 단 압박 가담량은 미검증 (교차 투영 — 실측 아님).','squad_entries W/WM 2행(fit_sim .936/.771); prescriptions measured(LM n=20)·fc26:opt:LM/RM; player_duties LM; v_player_profile n=38; FC26 2026-07-23(OVR78 POT84, PlayStyles 4종); obs#125·#128·#134·#143','n=38 충분하나 25/26 맨유·첼시 혼합 실측 — 에메리 체제 실측 0. .936은 첼시 25/26 6경기 소표본. 알론소·이라올라 핏은 교차 투영(실측 아님).','2026-08-11');
INSERT INTO player_evaluations VALUES(18,1,59,'C+ — 신규 영입 장기 프로젝트. WM fit_sim .833(wm_widemid/Build-Up, 확장 22경기 6.88 — 그레미우+빌라). obs#147에서 성향 긴장 1건: 인버티드 서사 vs widemid 커널 — 표본 혼합이라 잠정, 빌라 실측 6경기+ 축적 후 wm_insidefwd 대조 재판정 예정(duties ''⚠️ 방향 긴장'').','왼발 인버티드 — 우측 시작, 컷인 슛 개발 중, 전환·1v1 위협(영상 종합 가설). FC26 인벤티브 PlayStyle.','듀얼승 6.14(풀 백분위 87)의 나이 대비 경합 능력과 POT 83 성장폭. 약점: OVR 70으로 즉전력 아님, 컷인 슛은 ''개발 중'' 단계 — xG 백분위 35.','v_player_profile n=22(1475분), 평균 평점 6.88(풀 백분위 39), 듀얼승 6.14(백분위 87)가 유일한 상위 지표. xA 0.047(백분위 37)·키패스 0.41(백분위 30) — 창출 산출은 아직 하위.','MEDIUM — 커널 .833은 있으나 방향 긴장(인버티드 vs widemid)이 미해소·잠정 판정. obs#134의 우측 와이드 공백 후보이나 즉전력 미달.','LOW — 10번 포켓·윙백 어느 쪽에도 현 프로필이 닿지 않음 — 개발 단계 (교차 투영 — 실측 아님).','MEDIUM — 전환·1v1 위협과 듀얼 경합력은 수직 체제 원자재 (교차 투영 — 실측 아님).','squad_entries WM(fit_sim .833); prescriptions measured(RM n=15)·fc26:opt:LM/RM; player_duties RM(잠정); v_player_profile n=22; FC26(OVR70 POT83, 인벤티브); obs#147','n=22이나 그레미우(브라질)+빌라 혼합 표본 — 리그 강도·체제 모두 이질. 커널 판정 자체가 ''잠정'' 태그. 알론소·이라올라 핏은 교차 투영(실측 아님).','2026-08-11');
INSERT INTO player_evaluations VALUES(19,1,60,'C+ — 보유 ST 백업. fit_sim .643(st_false9/Attack, 확장 25경기 6.95)으로 스쿼드 내 최저 적합. obs#19가 핵심 판정: ''기본 시스템엔 부적합, 공중·직선 플랜B로만 유용''. 개인 산출은 나쁘지 않아(xG 0.508, 풀 백분위 87) 등급은 핏 불투명 쪽.','타깃형·직선형 9번 — 공중볼과 다이렉트 플레이 국면용. FC26 압박검증·인포서로 전방 압박 관여형.','xG 0.508/경기(풀 백분위 87)의 박스 마무리와 플랜B 공중 옵션. 약점: 연계·드롭 움직임이 에메리 원톱 3중 임무(점유/링크/채널)와 부정합 — fit_sim .643이 이를 수치로 확인, def 36.','v_player_profile n=25(1878분), 평균 평점 6.95(풀 백분위 49), xG 0.508(백분위 87 — 왓킨스 다음가는 풀 상위 득점 기대치). 듀얼승 백분위 36으로 타깃형 치고 경합 지표는 평범.','LOW — obs#19 판정 그대로 기본 시스템 부적합. 단 공중·직선 플랜B 한정으로는 유용(리드 시 딥블록·다이렉트 전환 국면).','LOW — 알론소 9번은 내려오는 false9(주앙 페드루형) — 아브라함의 st_false9 적합 .643이 낮고 타깃형 성향과 어긋남 (교차 투영 — 실측 아님).','MEDIUM — 직선성·전방 압박(압박검증)은 수직 전환 체제와 부분 부합 (교차 투영 — 실측 아님).','squad_entries ST(fit_sim .643); prescriptions measured(ST n=25)·fc26:opt:ST; v_player_profile n=25; FC26(OVR77, 압박검증·인포서); obs#19·#134 (player_duties 행 없음)','n=25이나 25/26 타 클럽(베식타시 임대 등) 혼합 표본 — 에메리 체제 실측 아님. player_duties 미작성. 알론소·이라올라 핏은 교차 투영(실측 아님).','2026-08-11');
INSERT INTO player_evaluations VALUES(20,2,13,'A — 알론소가 1티어 구단 공식 발언으로 직접 규정한 유일한 선수(obs#59: ''포켓 위치, 스트라이커 근처, 우리 10번 근처''), £117m 영국 기록 영입. 빌라 25/26 실측 56경기 4652분 평균 6.90으로 대량 표본이 있는 몇 안 되는 인원. 단 그 실측은 전부 에메리 체제 것이며(불변규칙 7), 알론소가 요구하는 중앙화(CAM 0.664)보다 좌측 인사이드(LW 0.778, LM wm_insidefwd 0.733)가 실측상 높아 ''지시 vs 실측'' 충돌이 미해결이다(obs#109 ③).','FC26 84/86(CAM 최적, 187cm): PAC77 SHO81 PAS81 DRI85 DEF67 PHY78. PlayStyles: 낮은 드리븐 슛·예리한패스·테크니컬·인포서·단일 클럽 선수(FC26 실조회값). 로밍형 중앙 크리에이터 — 인버티드 좌측에서 오른발 컷인, 미들서드 캐리.','특장점: 좌측 인사이드~중앙 10번 겸용의 유연성(알론소도 ''flexible'' 언급), 빅게임 천장(빌라 LW 실측 피크 8.84/8.46), 팔머와 실측 겹침 0.465로 낮아 좌우 분리 공존 가능. 약점: 우측 기용은 빌라 실측 최악 축(RM 8선발 평균 6.33, RM 적합 0.178 — 절대 금지 수준). 주앙 페드루와 실측 겹침 0.863(전체 최고)으로 좌측 과밀의 당사자(obs#109 ④). 엔소가 LM 0.750으로 근소 우위라 실측만으로는 이 칸 1순위가 아니다.','player_matches 56경기 4652분 평균 6.90(풀 57명 중 46백분위) — xG/경기 0.305(74백분위)·xA 0.202(77백분위)·키패스 1.91(74백분위). 태클·인터셉트 표본 0(미수집·공격수 특성). 빌라 CAM 21선발 평균 7.10 vs LW 13선발 6.91(천장형) vs RM 6.33(player_duties 실측).','HIGH — 유일하게 실측 근거가 있는 감독 핏: 에메리 25/26 체제에서 CAM 평균 7.10·LW 천장 실측을 직접 남겼다. 에메리의 ''자유 로밍 10번''(manager_profiles r1 traits) 원형 인원.','HIGH — 2×10의 좌측 축으로 처방(LM wm_insidefwd/Balanced, 실측 적합 0.700~0.733, 군최적 wideplm 0.725와 Δ0.025 노이즈 구간이라 알론소 명시 구상 유지 — obs#102 ④). 단 근거 그리드는 빌라 25/26 에메리 체제 것이며 첼시 실측이 아니다(체제 실측 아님).','MEDIUM — (교차 투영 — 실측 아님) 이라올라의 하프윙어 10번 슬롯(r3: 비르츠 cam_halfwinger)에 프로필상 이식 가능하나, 고강도 압박·수직 전환 체계에서의 비소유 기여는 실측 근거가 없다.','squad_entries(r2)·prescriptions(measured/projected)·v_player_profile·player_duties(r1 3행)·player_game_stats(FC26 2026-06-30)·obs#59·#102·#109','HIGH(빌라 실측·FC26 스탯) / MEDIUM(알론소 핏 — 체제 실측 0경기, 그리드는 에메리 체제)','2026-08-11');
INSERT INTO player_evaluations VALUES(21,2,31,'B — GK 실측 6경기 평균 6.80, gk_goalkeeper/Defend 적합 0.961로 스쿼드 전체 최고 적합치. 스위퍼형이 아님이 실측으로 확정됐고(sweeper 0.773), 알론소 원칙의 ''GK +1 수적우위''(obs#44)는 서사보다 실측 우선 원칙에 따라 채택되지 않았다. 다만 표본은 CHE 실측 표본은 25/26 마레스카·로즈니어 체제(알론소 체제 공식전 0경기, 첫 경기 8/24 풀럼)의 것이다.','자기진영 질량 1.00, 중심(51.8,10.8)의 정통 라인 키퍼. FC26 개인 스탯은 DB 미수집(player_game_stats에 행 없음 — 조회 불가 항목은 기재하지 않음).','특장점: GK 커널 적합 0.961로 처방 확실성이 스쿼드에서 가장 높다. 약점: 스위퍼 적합 0.773으로 낮아 알론소식 빌드업 +1 참여의 실측 근거가 없다 — 빌드업 관여를 요구받으면 검증 안 된 영역.','player_matches 1경기 90분 평균 6.90(46백분위·표본 부족), 키패스 2.0(89백분위, 1경기 값). 그리드 실측은 6경기 평균 6.80(prescriptions measured). 태클·인터셉트 0은 실제 0(GK 포지션 특성).','MEDIUM — (교차 투영 — 실측 아님) 에메리도 GK Defend 처방(r1: ''스위퍼 아님, 참여는 패스 옵션 수준'')이라 요구 프로필이 유사 — 이식 마찰은 작을 것.','MEDIUM — 처방은 gk_goalkeeper/Defend 유지(0.961). 알론소가 GK 빌드업 참여를 요구할 경우 스위퍼 적합 0.773이 걸림돌. (체제 실측 아님 — 25/26 타 감독 표본)','LOW~MEDIUM — (교차 투영 — 실측 아님) 하이라인·고압박 체계는 스위퍼형 GK를 선호하는데 산체스의 스위퍼 적합은 0.773으로 낮다.','squad_entries(r2)·prescriptions(measured/projected)·v_player_profile·obs#44','HIGH(그리드 6경기) / LOW(이벤트 스탯 — player_matches 1경기)','2026-08-11');
INSERT INTO player_evaluations VALUES(22,2,32,'B — RB 실측 6경기 평균 6.40, fb_att_wb/Support 0.862. 전방 0.34/자기진영 0.44의 균형형 전진 풀백으로, 알론소 체계의 ''폭 독점 윙백''(obs#46: 크로서가 아니라 득점자, 프림퐁형) 요구에 부합하는 유일한 보유 우측 인원이자 전방 4인 중 유일한 수비 질량 공급자. 표본은 CHE 실측 표본은 25/26 마레스카·로즈니어 체제(알론소 체제 공식전 0경기, 첫 경기 8/24 풀럼)의 것.','균형형 전진 풀백, 중심(81.5,46.3). wingback/Support 0.830이 차순위로 역할 간 격차가 작다. FC26 개인 스탯 DB 미수집.','특장점: 우측 윙백 슬롯의 유일 적임(팔레스트라 영입 전 기준)이며 공수 질량 배분이 균형적. 약점: 평균 6.40은 스쿼드 실측 인원 중 최저 — 프림퐁의 득점 관여(obs#46 원형)를 재현할 공격 산출 근거가 없다.','player_matches 행 0 — 이벤트 스탯·백분위 산출 불가. 그리드 실측 6경기 평균 6.40(prescriptions measured 기재값)이 유일한 정량 근거.','MEDIUM — (교차 투영 — 실측 아님) 에메리는 풀백을 한 명씩만 전진(C2). 균형형 프로필이라 전진측·잔류측 어느 쪽도 소화 가능할 것으로 보이나 실측 없음.','MEDIUM~HIGH — 구조상 유일한 우측 폭 공급자(RB fb_att_wb/Support 0.862, manager_profiles r2 implementation)이나 산출력이 원형(프림퐁) 대비 미검증. (체제 실측 아님 — 25/26 타 감독 표본)','MEDIUM — (교차 투영 — 실측 아님) 이라올라 우측은 인버티드(프림퐁 fb_inverted 성향 실측)가 기준선 — 귀스토의 인버티드 실측 근거는 없다.','squad_entries(r2)·prescriptions(measured/projected)·obs#46','MEDIUM(그리드 6경기) / 이벤트 스탯 없음','2026-08-11');
INSERT INTO player_evaluations VALUES(23,2,33,'B+ — RCB cb_bpd/Aggressive 0.943(신커널)으로 백3 우측 확정 인원. 실측 6경기 평균 6.47, RCB 0.953 vs LCB 0.239~0.424로 완전한 우측 전용. 전방 0.05/자기진영 0.70 — 백3 중 가장 순수한 수비형으로 obs#58의 ''강력한 CB 1'' 역할에 대응. 표본은 CHE 실측 표본은 25/26 마레스카·로즈니어 체제(알론소 체제 공식전 0경기, 첫 경기 8/24 풀럼)의 것.','순수 수비형 우측 CB, 중심(66.5,31.8). 세 슬롯 전수 재산출(obs#102 ②)에서 LCB 0.256/CCB 0.669/RCB 0.943 — 자기 자리가 압도적. FC26 개인 스탯 DB 미수집.','특장점: 수비 지표가 풀 최상위 — 듀얼승 10.0(98백분위)·태클 2.0(87백분위)·인터셉트 3.0(100백분위). 단 전부 1경기 값(표본 부족). 약점: 좌측 이동 불가(LCB 0.239~0.424)라 백3 좌우 로테이션 유연성이 없다. 내구성(부상 이력)은 본 DB에 근거 행이 없어 판단 보류.','player_matches 1경기 89분 평균 7.90(91백분위) — 듀얼승 10.0(98백분위)·태클 2.0(87백분위)·인터셉트 3.0(100백분위)·키패스 0(CB 특성). 전 지표 1경기 표본이라 백분위는 참고치. 그리드 실측은 6경기 평균 6.47.','MEDIUM~HIGH — (교차 투영 — 실측 아님) 에메리 백4의 볼플레잉 CB 요구(r1 buildup)와 cb_bpd 프로필이 일치하나 백4 RCB 실측은 없다.','HIGH — 백3 우측의 확정 인선(RCB cb_bpd/Aggressive 0.943, obs#102에서 불변에 가까움). (체제 실측 아님 — 25/26 타 감독 표본)','MEDIUM~HIGH — (교차 투영 — 실측 아님) 하이라인 커버형 CB 요구 — 순수 수비형 프로필은 맞으나 압박 체계 실측 없음.','squad_entries(r2)·prescriptions(measured/projected)·v_player_profile·obs#58·#102','HIGH(그리드 6경기·슬롯 전수 산출) / LOW(이벤트 스탯 1경기)','2026-08-11');
INSERT INTO player_evaluations VALUES(24,2,34,'B — CCB 슬롯 신설의 근거 인선(obs#102 ②: CCB 0.873 > RCB 0.744 > LCB 0.665, 중심 x 52.7로 정확히 중앙). 중앙 CB를 좌우로 흡수하면 −0.118 손실이라 백3 중앙 배치가 수치로 성립한다. 단 45분+ 표본 3경기로 표본 부족이고, 그리드는 RCB 표기 경기의 것을 CCB에 쓴 것(원 캐비앗). 표본은 CHE 실측 표본은 25/26 마레스카·로즈니어 체제(알론소 체제 공식전 0경기, 첫 경기 8/24 풀럼)의 것.','FC26 80/82(CB 최적, 190cm): PAC66 SHO53 PAS69 DRI70 DEF81 PHY78. PlayStyles: 프리시전 헤딩·슬라이딩태클(FC26 실조회값). CB/RB 겸용 등록.','특장점: 백3 세 슬롯 중 유일하게 중앙 성향(세 CB 전수 산출에서 셋 다 자기 자리 최고 — 그가 빠지면 CCB 슬롯 자체가 흔들린다). 공중·태클형 PlayStyles가 ''강력한 CB'' 축과 정합. 약점: 표본 3경기(표본 부족) — 백3 처방 중 근거가 가장 얇은 축의 하나. PAC 66으로 하이라인 뒷공간 커버는 게임 내 제약.','player_matches 행 0 — 이벤트 스탯·백분위 산출 불가. 그리드 실측 3경기 평균 6.47(prescriptions measured 기재값, 표본 부족 명기).','MEDIUM — (교차 투영 — 실측 아님) 백4 체계에서는 CCB 이점이 사라지고 RCB 0.744로 포파나(0.943)에 밀린다.','MEDIUM~HIGH — CCB cb_bpd/Aggressive 0.873으로 신설 슬롯의 확정 인선이나 표본 3경기. (체제 실측 아님 — 25/26 타 감독 표본)','LOW~MEDIUM — (교차 투영 — 실측 아님) FC26 PAC 66은 하이라인·즉시 압박 체계의 뒷공간 노출 지점.','squad_entries(r2)·prescriptions(measured/projected)·player_game_stats(FC26 2026-06-30)·obs#102','MEDIUM(그리드 3경기 — 표본 부족) / HIGH(FC26 스탯)','2026-08-11');
INSERT INTO player_evaluations VALUES(25,2,35,'B — 실측이 포지션 서사를 정정한 사례: ''쿠쿠렐라 후임 LB'' 제안을 실측이 반박(LB 0.717→신커널 0.469)하고 LCB cb_bpd/Aggressive 0.930(신커널 0.850)으로 좌측 CB 프로필이 확정됐다(obs#102 ②: ''하토는 LB가 아니라 좌측 CB'' 반박이 더 강해짐). 6경기 평균 6.52. 표본은 CHE 실측 표본은 25/26 마레스카·로즈니어 체제(알론소 체제 공식전 0경기, 첫 경기 8/24 풀럼)의 것.','좌측 볼플레잉 CB, 중심(27.0,35.3), 전방 0.12/자기진영 0.62. obs#58의 ''볼플레잉 CB 2'' 중 한 축. RCB 0.102로 우측 이동 불가. FC26 개인 스탯 DB 미수집.','특장점: 백3 좌측의 확정 인선이며 볼플레잉 축. 약점: LB 겸용 불가 판정(0.469)이 좌 윙백 인선 공백(obs#109 ①: 확정 영입 2인이 전부 우측 자원)을 해소하지 못하는 원인 — 그의 전용성이 스쿼드 구조 최약 슬롯을 그대로 남긴다. 이벤트 스탯 평균 6.70(25백분위, 1경기)으로 낮은 편.','player_matches 1경기 79분 평균 6.70(25백분위·표본 부족) — 듀얼승 2.0(34백분위)·태클 1.0(55백분위)·인터셉트 0(실제 0, 1경기). 그리드 실측 6경기 평균 6.52.','MEDIUM — (교차 투영 — 실측 아님) 에메리 백4 LCB 볼플레잉 요구와 프로필 일치 — 단 백4 실측 없음.','HIGH — LCB cb_bpd/Aggressive 0.850(신커널)으로 백3 좌측 확정. 단 커널 교체로 −0.080 하락한 이력 있음(obs#102 ①). (체제 실측 아님 — 25/26 타 감독 표본)','MEDIUM — (교차 투영 — 실측 아님) 좌측 CB 프로필 자체는 이식 가능하나 압박 체계 실측 없음.','squad_entries(r2)·prescriptions(measured/projected)·v_player_profile·obs#58·#102·#109','HIGH(그리드 6경기·슬롯 전수 산출) / LOW(이벤트 스탯 1경기)','2026-08-11');
INSERT INTO player_evaluations VALUES(26,2,36,'A — 피벗의 실질 기둥. LDM dm_dlp/Roaming 0.941(6경기 평균 7.00, 신커널 불변), 신커널에서 RDM도 0.871로 급등해 양측 겸용이 가능해졌다(obs#102 ⑤ — 단 이동은 순 −0.028로 기각, 우발 대비로만 기록). 핵심 긴장: obs#116이 확정한 기능축 실측(듀얼승 4.6·인터셉트 1.25·볼회수 5.4 전부 피벗 3인 중 1위, 키패스 0.6 최하위)은 그가 명백한 볼위너임을 말하는데, 현 처방은 dm_dlp(창조형)를 유지한다 — 움직임 적합 +0.126을 사고 기능 정합을 포기한 트레이드(지불액 0.246~0.294, 사용자 판단 보류 사항). 표본은 CHE 실측 표본은 25/26 마레스카·로즈니어 체제(알론소 체제 공식전 0경기, 첫 경기 8/24 풀럼)의 것.','움직임은 창조형(백라인 옆 하강, obs#44의 ''압박 유인 후 관통'' 정합 — 자기진영 0.40)인데 기능은 볼위너 — ''첼시의 카마라''(obs#116). 중심(47.6,44.5)의 중앙 피벗. FC26 개인 스탯 DB 미수집.','특장점: 수비 3지표(듀얼·인터셉트·회수) 피벗 내 전부 1위 + 패스 성공률 90.7%·경기당 66.0회로 볼순환 볼륨도 최고 — 파괴와 순환을 겸한다. 신커널 기준 좌우 피벗 양측 가용. 약점: 창조 산출 최하위(키패스 0.6·xA 0.056) — dm_dlp 처방이 요구하는 창조 축을 기능축 실측이 지지하지 않는다(obs#116 ⑤). 듀얼 4.6은 첼시 3인 내부 비교이지 리그 절대 기준이 아님(카마라 8.4의 절반 수준).','player_matches 9경기 800분 평균 7.08(63백분위) — 듀얼승 4.22(81백분위)·인터셉트 1.33(89백분위)·태클 1.33(62백분위)·키패스 0.67(43백분위)·xA 0.056(47백분위). 기능축 stats_json 8경기: 듀얼승 4.6·인터셉트 1.25·볼회수 5.4·키패스 0.6·패스 66.0(90.7%).','HIGH — (교차 투영 — 실측 아님) 에메리 더블 피벗의 볼위닝 축(r1: 오나나·카마라=dm_holding, obs#32의 기능 분화 원칙)에 기능축 프로필이 정확히 대응한다.','HIGH — 하강 피벗(dm_dlp/Roaming 0.941)이 알론소 빌드업 원칙(obs#44)과 정합하며 manager_profiles r2가 지명한 핵심 인원. 단 obs#116의 기능축 긴장(볼위너인데 창조형 처방·피벗 2인 모두 dm_dlp로 분화 없음 — id=8 reference의 샤카+팔라시오스 분화와 어긋남)이 미해결이고, 표본이 체제 실측이 아니다(25/26 타 감독 표본).','HIGH — (교차 투영 — 실측 아님) 고강도 압박·즉시 탈취 체계에서 볼회수 5.4/경기 프로필은 원형 적합 — 단 실측 없음.','squad_entries(r2)·prescriptions(measured/projected)·v_player_profile·obs#44·#102·#109·#116','HIGH(움직임 6경기+기능축 8경기 실측) / MEDIUM(알론소 체제 이식 — 공식전 0경기)','2026-08-11');
INSERT INTO player_evaluations VALUES(27,2,37,'A — 실측 6경기 평균 7.28로 첼시 필드 플레이어 최고. 실측 형태는 피벗 라벨보다 좌측 와이드 플레이메이커(LM wm_wideplm/Attack 0.750 > LDM 0.698 > CAM 0.631, 중심 35.3,57.0 좌측 편향). obs#116이 기능축을 확정: 키패스 2.6으로 카이세도의 4배 이상 — 피벗 2인의 기능 분화에서 명백한 창조 축이다. RDM은 0.535로 부적합(''카이세도와 같은 쪽(좌측)을 원한다'' 판정 유지, obs#116 ⑥). 표본은 CHE 실측 표본은 25/26 마레스카·로즈니어 체제(알론소 체제 공식전 0경기, 첫 경기 8/24 풀럼)의 것.','창조형 좌측 성향 미드필더 — 전방 0.49/자기진영 0.21로 피벗 후보 중 가장 전진적. LM 0.750이 로저스(0.700)보다 높아 실측만 보면 LM 칸 1순위(obs#102 ⑥, 격차 0.050). FC26 개인 스탯 DB 미수집(웨스트햄 ''페르난데스''는 동명이인).','특장점: 창조 지표 풀 최상위 — 키패스 2.63(94백분위)·xA 0.213(83백분위), 평점 7.44(84백분위, player_matches 8경기). 약점: 수비 질량 최소(자기진영 0.21) — 그를 LDM에 두면 좌 윙백 공백 지역의 수비 보호가 사라진다(obs#102 ⑷ 카이세도 이동 기각의 근거). RDM 0.535로 우측 피벗 불가.','player_matches 8경기 718분 평균 7.44(84백분위) — 키패스 2.63(94백분위)·xA 0.213(83백분위)·듀얼승 4.0(77백분위)·태클 1.38(64백분위)·인터셉트 0.63(70백분위). 기능축 stats_json 8경기: 키패스 2.6·xA 0.213·듀얼승 4.0·볼회수 3.5.','MEDIUM~HIGH — (교차 투영 — 실측 아님) 에메리 더블 피벗의 창조 축(틸레만스=dm_dlp 원형, obs#32)에 기능 프로필이 대응하나 수비 질량이 얇다.','HIGH — 샤카 대응 창조 축(id=8 reference·obs#58 ''엔소+카이세도 더블 피벗'' 공통 지목). 단 현 처방은 그를 피벗이 아닌 LM 후보로 두며, 소스 배정(엔소 LDM 창조)으로의 변경은 움직임 적합 −0.126의 대가가 있어 미실행(obs#116 ④). (체제 실측 아님 — 25/26 타 감독 표본)','MEDIUM — (교차 투영 — 실측 아님) 수직 전환 체계의 전진 패스 축으로는 맞으나, 고강도 압박의 비소유 요구 대비 수비 질량(자기진영 0.21)이 최소라는 점이 리스크.','squad_entries(r2)·prescriptions(measured)·v_player_profile·obs#58·#102·#116','HIGH(움직임 6경기+기능축 8경기 실측) / MEDIUM(알론소 체제 이식 — 공식전 0경기)','2026-08-11');
INSERT INTO player_evaluations VALUES(28,2,38,'B — 실측 6경기 평균 6.63, RM wm_winger/Balanced 0.875, 전방 0.59/자기진영 0.20의 터치라인형 윙어. 문제는 선수가 아니라 구조: 알론소 3-4-2-1에는 윙어 슬롯이 아예 없고(obs#61 — 첼시의 구조적 모순은 윙어 과잉), 네투의 실측이 그 모순의 실측 근거로 지목돼 있다. LM 0.316으로 우측 전용. 표본은 CHE 실측 표본은 25/26 마레스카·로즈니어 체제(알론소 체제 공식전 0경기, 첫 경기 8/24 풀럼)의 것.','터치라인형 우측 윙어(중심 65.4,61.8) — insidefwd 0.847이 근접 차순위라 인사이드 변형 여지는 있음(Δ0.028은 노이즈 구간이라 우열 단정 불가). FC26 개인 스탯 DB 미수집.','특장점: 우측 폭 공급 자체는 확실(적합 0.875). player_matches 1경기 평균 8.20(98백분위)이 눈에 띄나 1경기 값(표본 부족). 약점: 체계 부적합 — 알론소의 폭 담당자는 윙백이라(obs#46) 그의 본 직무 슬롯이 처방에 없다. 팔머(RM 0.845)와 슬롯 경합 시 실측 근거가 밀린다.','player_matches 1경기 59분 평균 8.20(98백분위·표본 부족) — 키패스 2.0(89백분위)·듀얼승 2.0(34백분위), 인터셉트 0은 실제 0(1경기·윙어 특성). 그리드 실측 6경기 평균 6.63.','MEDIUM~HIGH — (교차 투영 — 실측 아님) 에메리 4-2-3-1 Wide의 우측 와이드 슬롯이 존재하나, 그 칸의 처방은 뱅크 복귀형(wm_widemid/Support)이라 전방 0.59/자기진영 0.20의 네투와 질량 방향이 반대다.','LOW~MEDIUM — 개인 적합(0.875)이 아니라 슬롯 부재가 문제: 3-4-2-1에 윙어 칸이 없다(obs#61). 로테이션·플랜B(4-3-3 잔존 시나리오) 자원. (체제 실측 아님 — 25/26 타 감독 표본)','MEDIUM~HIGH — (교차 투영 — 실측 아님) 이라올라 체계는 정통 윙어 슬롯이 살아 있는 편(살라 wm_winger/Attack 임시 처방)이라 세 감독 중 직무 보존이 가장 좋다.','squad_entries(r2)·prescriptions(measured)·v_player_profile·obs#46·#61','HIGH(그리드 6경기) / LOW(이벤트 스탯 1경기)','2026-08-11');
INSERT INTO player_evaluations VALUES(29,2,39,'A — 2×10의 우측 축. 실측이 ''CAM 10번'' 라벨을 정정한 대표 사례: 중심(65.0,59.9) 우측 편향, RM wm_wideplm/Attack 0.845 ≫ CAM 0.676, LM 0.152 완전 부적합. 6경기 평균 6.82, 신커널에서도 0.845 불변(obs#102 ①). 로저스와 실측 겹침 0.465로 낮아 좌우 분리 공존이 구조적으로 가능 — 알론소의 ''팔머 병용 플랜''(obs#59)을 실측이 지지한다. 표본은 CHE 실측 표본은 25/26 마레스카·로즈니어 체제(알론소 체제 공식전 0경기, 첫 경기 8/24 풀럼)의 것.','우측 포켓 플레이메이커(호프만=우 커넥터 대응, id=8 reference), 전방 0.59/자기진영 0.16으로 수비 질량 최소급. 알론소는 ''10번 근처''로 말했지만 실측 중심 x=65는 우측 편향(projected 캐비앗). FC26 개인 스탯 DB 미수집.','특장점: 우측 하프스페이스 전용성이 명확해 처방 확실성이 높다(신커널 불변 7칸 중 하나). 수비 스탯도 1경기 기준 태클 2.0(87백분위)·인터셉트 1.0(85백분위)으로 나쁘지 않음. 약점: LM 0.152 — 좌측 이동 불가라 로저스 부재 시 좌측 커버 불가. 자기진영 질량 0.16으로 비소유 국면 기여는 얇다.','player_matches 1경기 85분 평균 7.20(77백분위·표본 부족) — 키패스 1.0(63백분위)·듀얼승 4.0(77백분위)·태클 2.0(87백분위)·인터셉트 1.0(85백분위, 전부 1경기 값). 그리드 실측 6경기 평균 6.82.','MEDIUM — (교차 투영 — 실측 아님) 에메리 우측 와이드는 뱅크 복귀형(wm_widemid/Support) 처방이라 파머의 전방 편중(0.59/0.16)과 어긋난다. 자유 로밍 10번 칸이라면 적합하나 그 칸 실측은 없다.','HIGH — RM wm_wideplm/Attack 0.845(신커널 불변)로 2×10 우측 확정 인선이며 알론소 본인이 로저스와의 연계를 공언(obs#59). (체제 실측 아님 — 25/26 타 감독 표본)','MEDIUM~HIGH — (교차 투영 — 실측 아님) 살라의 우측 인사이드 슬롯(r3 traits)과 형태가 유사 — 단 압박 기여 요구가 미검증.','squad_entries(r2)·prescriptions(measured/projected)·v_player_profile·obs#59·#102','HIGH(그리드 6경기·신커널 불변) / LOW(이벤트 스탯 1경기)','2026-08-11');
INSERT INTO player_evaluations VALUES(30,2,40,'A− — 서사-실측 일치 사례: ''내려오는 9번''(obs#58) 서술을 실측이 지지한다(ST 0.624 < CAM 0.718 — 하강 성향이 수치로 확인). 6경기 평균 6.92, 처방은 그 성향에 가장 가까운 ST 역할인 st_false9/Build-Up. 구조적 리스크의 당사자: 로저스와 실측 겹침 0.863(전체 최고) — 좌측 10번과 9번이 같은 공간을 쓴다(obs#109 ④: 좌측 과밀+무보호). 표본은 CHE 실측 표본은 25/26 마레스카·로즈니어 체제(알론소 체제 공식전 0경기, 첫 경기 8/24 풀럼)의 것.','드롭형 9번(보니페이스 대응, id=8 reference: 압박 선봉+링크), 중심(45.1,61.4), 전방 0.61/자기진영 0.18. ST 슬롯 적합 0.624는 스쿼드 처방 10칸 중 최저 — 형태상 순수 9번이 아니기 때문. FC26 개인 스탯 DB 미수집.','특장점: 연계·하강 프로필이 알론소 원형(9번=압박 선봉+링크)과 정합하고 평점 산출도 상위(1경기 8.0, 그리드 6경기 6.92). 약점: 처방 적합 0.624가 10칸 중 최저 — 박스 내 고정 9번 산출은 실측 형태 밖. 로저스 겹침 0.863은 알론소 체계의 실질 리스크 지점(projected 명기).','player_matches 1경기 85분 평균 8.00(95백분위·표본 부족) — 키패스 1.0(63백분위)·듀얼승 2.0(34백분위)·태클 1.0(55백분위), 인터셉트 0은 실제 0(1경기·ST 특성). xG는 표본 0으로 산출 불가. 그리드 실측 6경기 평균 6.92.','MEDIUM — (교차 투영 — 실측 아님) 에메리 4-2-3-1의 9번은 왓킨스형 압박 선도+뒷공간 침투가 원형 — 하강 연계형과 방향이 다르나 겸용 불가 근거도 없다.','HIGH — ''내려오는 9번'' 서사를 실측이 지지하는, 서사-실측이 일치하는 드문 칸. 단 좌측 과밀(로저스 겹침 0.863)의 해소는 8/24 풀럼 이후 실측 대기. (체제 실측 아님 — 25/26 타 감독 표본)','MEDIUM~HIGH — (교차 투영 — 실측 아님) 파이널서드 탈취→즉시 슛 체계에서 전방 압박 선봉+링크 프로필은 원형 적합 — 실측 없음.','squad_entries(r2)·prescriptions(measured/projected)·v_player_profile·obs#58·#102 ⑦·#109','HIGH(그리드 6경기·겹침 산출) / LOW(이벤트 스탯 1경기)','2026-08-11');
INSERT INTO player_evaluations VALUES(31,2,41,'B+ — 처방 전체의 최약 칸이자 가장 흥미로운 하이브리드. RDM dm_dlp 처방(신커널에서 Roaming 0.772→0.579로 붕괴, Build-Up 0.656으로 포커스만 교체 — obs#102 ③)이나 45분+ 표본 3경기(표본 부족 — ''이 처방의 가장 약한 칸'' 명기). 실측 3경기 평균 7.33은 스쿼드 최고치지만 표본이 이를 뒷받침하지 못한다. 알론소가 트렌트에게 준 ''inverted role'' 지시(obs#57)의 첼시 대응 인원. 표본은 CHE 실측 표본은 25/26 마레스카·로즈니어 체제(알론소 체제 공식전 0경기, 첫 경기 8/24 풀럼)의 것.','인버티드 윙백/피벗 하이브리드 — RDM 0.772(구커널) > RB fb_inverted/Attack 0.692, 중심(73.3,52.3). 기능축(obs#116)에서 xA 0.244로 3인 중 최고이나 패스 볼륨 최소(53.1회)·pos가 M/D 혼재라 기능값 자체가 역할 혼재값. FC26 개인 스탯 DB 미수집.','특장점: xA 0.244(93백분위)로 창조 산출 최상급 + 패스 성공률 94.1%로 정확도 최고 — 우측 전개 축의 근거. 약점: ① 표본 3경기 ② obs#58(1티어)·id=8이 공통 지목한 ''엔소+카이세도'' 피벗에서 이탈한 인선인데 그 이탈이 움직임 적합 +0.126의 구매였음이 뒤늦게 정량화됨(obs#116 ④) ③ 카이세도 RDM 0.871 급등으로 ''유일 적합자'' 서술 폐기(obs#109 ②) — 결장 시 대체는 서나 지위는 상대화됨.','player_matches 7경기 592분 평균 7.14(70백분위) — xA 0.244(93백분위)·키패스 1.43(69백분위)·태클 1.71(72백분위)·인터셉트 0.71(72백분위)·듀얼승 3.43(53백분위). 기능축 stats_json 7경기: xA 0.244·키패스 1.4·패스 53.1회(94.1%). 45분+ 그리드는 3경기(표본 부족).','MEDIUM — (교차 투영 — 실측 아님) 에메리 C2(풀백 한 명만 전진)의 전진측 RB로 쓸 수 있는 프로필이나, 에메리 처방의 우측은 잔류형(fb_wingback/Balanced)이라 방향이 어긋난다.','MEDIUM~HIGH — 트렌트 ''inverted role''의 대응 인원으로 기능(창조·전개)은 맞으나, 처방 근거(그리드 3경기·Δ0.001 동률 판정)가 스쿼드에서 가장 얇다 — 8/24 풀럼이 첫 검증. (체제 실측 아님 — 25/26 타 감독 표본)','HIGH — (교차 투영 — 실측 아님) 이라올라 우측의 인버티드 RB(프림퐁 fb_inverted 실측 성향)와 형태가 가장 직접 대응하는 스쿼드 인원.','squad_entries(r2)·prescriptions(measured/projected)·v_player_profile·obs#57·#102·#109·#116','MEDIUM(그리드 3경기 — 표본 부족·기능값 역할 혼재) / HIGH(이벤트 7경기)','2026-08-11');
INSERT INTO player_evaluations VALUES(32,2,42,'B — 실측 3경기(표본 부족) 평균 6.77, RM wm_widemid/Support 0.789. 전방 0.51/자기진영 0.29로 네투보다 복귀 성향이 큰 우측 와이드 — 순수 윙어보다 지원형에 가깝다는 것이 초기 실측의 시사점. 우측은 팔머(0.845)·네투(0.875)와 3파전이라 슬롯 경쟁이 스쿼드에서 가장 치열한 칸. 표본은 CHE 실측 표본은 25/26 마레스카·로즈니어 체제(알론소 체제 공식전 0경기, 첫 경기 8/24 풀럼)의 것.','복귀 성향 우측 와이드(중심 76.1,58.2), winger/Balanced 0.746이 차순위(Δ0.043 — 노이즈 상단이라 우열 단정 보류). FC26 개인 스탯 DB 미수집. 연령·성장 곡선 관련 행도 DB에 없어 잠재력 서술은 하지 않는다.','특장점: 복귀 질량(자기진영 0.29)이 우측 와이드 3인 중 최대 — 비소유 국면 기여가 필요한 라인업에서 차별점. 약점: 표본 3경기로 모든 판단이 잠정적. 알론소 체계에 윙어 슬롯이 없다는 구조 문제(obs#61)는 네투와 공유.','player_matches 행 0 — 이벤트 스탯·백분위 산출 불가. 그리드 실측 3경기 평균 6.77(prescriptions measured 기재값, 표본 부족 명기)이 유일한 정량 근거.','MEDIUM~HIGH — (교차 투영 — 실측 아님) 에메리 우측 와이드 처방이 정확히 wm_widemid/Support(뱅크 복귀형) — 세 감독 처방 중 실측 성향과 역할 라벨이 유일하게 일치한다. 단 실측 자체가 3경기.','MEDIUM — 우측 로테이션 자원(RM 0.789). 2×10 우측은 팔머 확정이라 출전 경로가 좁다. (체제 실측 아님 — 25/26 타 감독 표본)','MEDIUM — (교차 투영 — 실측 아님) 측면 압축·복귀 요구와 복귀 성향은 맞으나 표본이 얇아 판단 보류 수준.','squad_entries(r2)·prescriptions(measured)·obs#61','LOW~MEDIUM(그리드 3경기 — 표본 부족, 이벤트 스탯 없음)','2026-08-11');
INSERT INTO player_evaluations VALUES(33,3,43,'B+ — 25/26 실측 6경기 평균 6.80(중심 53.0,11.4), gk_goalkeeper/Defend 적합 0.979로 스쿼드 최고 커널 정합(obs#120). sweeper 변형은 0.821로 뚜렷이 낮아 스위퍼형이 아니라는 실측 판정. 8/9 모나코 친선 45분 6.8. 단 표본이 전임(슬롯) 체제 것이고 FC26 인게임 스탯은 미수집 상태라 상한 판정은 유보.','정통 골키퍼형 — 실측 그리드가 골문 근방에 강하게 응집(gk_goalkeeper 0.979 > Balanced 0.969 > sweeper 0.821). ''스위퍼 키퍼'' 서사와 달리 실측 위치 분포는 라인 뒤 잔류형. Δ0.01 수준(Defend vs Balanced)은 EA 노이즈라 포커스 우열은 단정하지 않는다.','역할 커널 정합도가 팀 내 최고(0.979) — 어느 감독 체제에서든 GK 슬롯 배치 리스크가 가장 낮다. 약점: 하이라인 체제에서 요구될 스위핑 반경이 실측상 확인되지 않음(sweeper 0.821). FC26 능력치·PlayStyles 미수집이라 배급 품질은 데이터로 말할 수 없다.','player_matches 실측은 8/9 모나코 친선 1경기(45분, 평점 6.80)뿐 — 3팀 풀(57행) 대비 평점 백분위 30%지만 n=1 표본 부족으로 서열 의미 없음. 25/26 시즌 실측은 prescriptions(measured): 6경기 평균 6.80. KP/태클/인터셉트 0은 실제 0(GK 포지션 특성상 정상).','HIGH — (교차 투영 — 실측 아님) 에메리 빌라 처방이 정확히 GK gk_goalkeeper/Defend(스위퍼 아님, 빌라 실측 0.961)이고 알리송의 실측 최적이 같은 역할·포커스 0.979다. 짧은 빌드업 참여는 ''패스 옵션 수준''이라는 에메리 요구와 잔류형 실측 분포가 정합.','MEDIUM — (교차 투영 — 실측 아님) 알론소는 Short Passing 백3 빌드업에 GK를 후방 수적 우위 요원으로 쓴다. 역할 자체는 무리 없으나 배급 품질을 가릴 FC26 스탯·기능축 실측이 없어 상향 판정 근거 부족.','MEDIUM — ⚠️ 체제 실측 아님(이라올라 공식전 0경기, 8/23 뉴캐슬이 첫 경기). 이라올라 하이라인+맨투맨 프레스(obs#68)는 라인 뒤 넓은 커버를 요구할 개연성이 있는데 실측 sweeper 적합은 0.821로 gk형(0.979)보다 낮다. 다만 이 그리드는 25/26 슬롯 체제 표본이라 이라올라 지시 하 재측정 필요 — regime3 implementation도 ''잠정 GK/Defend'' 배치(confidence LOW).','squad_entries(r3) · prescriptions#measured(GK, n=6) · v_player_profile(n=1, 8/9 모나코) · obs#120 · manager_profiles r1/r2/r3','MEDIUM — 커널 적합은 신커널 재산출값(obs#120)으로 확정적이나, 표본이 전임 체제 6경기+친선 1경기이고 FC26 스탯·player_duties 미수집.','2026-08-11');
INSERT INTO player_evaluations VALUES(34,3,44,'A− — 25/26 실측 6경기 평균 7.15(필드 내 상위), LCB cb_bpd/Aggressive 0.912(obs#120 신커널). LCB 0.896 > CCB 0.789로 백3 중앙이 아닌 좌측 CB 판정. 공중 경합 부담 78%로 리그 1위 집중(obs#77)이라는 ''단일장애점'' 지위가 등급을 지탱하면서 동시에 리스크다. 코나테 이탈로 26/27 가용 시니어 CB가 사실상 본인 1명(obs#69).','볼 플레잉 + 전진 수비형 CB(cb_bpd/Aggressive, 차2 Build-Up 0.814). 전방 질량 0.10/자기진영 0.61의 후방 정박형 분포. 25/26 수비액션 8.1→11.3/90 급증(obs#77)은 팀 전방 수비 실패로 CB 부하가 커진 증거 — 개인 활동량 지표이자 팀 구조 경고.','공중 장악(팀 공중 경합의 78% 담당, 리그 1위 — obs#77)과 빌드업 출구 역할. 약점: 상대 롱볼 피허용 리그 1위(571회) 국면에서 공중 버팀목이 본인 1명에 집중된 단일장애점 — 본인 결장 시 대체 불가. 나이 축 데이터(FC26 스탯) 미수집.','8/9 모나코 친선 1경기: 59분 평점 6.10, 지상 경합 승 3, 인터셉트 3(3팀 풀 대비 인터셉트 백분위 96%·평점 백분위 0%) — n=1이라 양방향 모두 서열 의미 없음. 25/26 실측(prescriptions measured): 6경기 평균 7.15.','HIGH — (교차 투영 — 실측 아님) 에메리 처방이 양 CB cb_bpd(볼 플레잉)이고 실측 최적이 정확히 cb_bpd. 단 빌라는 ''두 CB 동시 Aggressive는 rest-defense 붕괴''로 기각한 이력(obs#13, obs#120 ⓐ 재인용)이라 포커스는 Build-Up 계열 조정 여지.','HIGH — (교차 투영 — 실측 아님) 알론소 백3는 전 CB cb_bpd/Aggressive + Short Passing(r2 implementation) — 실측 역할·포커스가 그대로 일치. 좌측 CB 실측(LCB 0.896)이라 백3 좌 스토퍼 투영이 자연스럽다.','HIGH — ⚠️ 체제 실측 아님. 이라올라는 CB가 내려오는 스트라이커를 따라 박스 밖까지 나가는 맨마킹을 명시 지시(obs#68·#69)하고 Aggressive 커널이 이 문법과 정합. 다만 obs#69가 ''이 지시를 수행할 인원이 없다''고 지적한 그 유일한 시니어 CB가 본인이며, 롱볼 대응은 맨마킹에 더 치명적(obs#77)이라 부하·리스크 집중은 체제 최대 검증 항목.','squad_entries(r3) · prescriptions#measured(LCB, n=6) · v_player_profile(n=1) · obs#69·#77·#120 · manager_profiles r1/r2/r3','MEDIUM-HIGH — 커널 값은 신커널 확정(obs#120), 팀 구조 서술은 Opta 인용(obs#77). 표본은 전임 체제.','2026-08-11');
INSERT INTO player_evaluations VALUES(35,3,45,'B+ — 25/26 실측 6경기 평균 6.88, RCB cb_bpd/Aggressive 0.938(obs#120 신커널, 판다이크 0.912와의 Δ0.026은 EA 노이즈 — 우열 없음). ⚠️ 소속 상태 데이터 불일치: prescriptions와 obs#69는 ''2026-07-01 레알 마드리드 자유이적 이탈''로 기록했는데 squad_entries(r3)에는 lh=OWNED로 남아 있다. 실측 행은 ''26/27 RCB 슬롯의 유일한 실측 기준선''으로서 대체자 판정용으로 보존된 것.','전진 수비형 볼 플레잉 CB(cb_bpd/Aggressive 0.938, 차2 Build-Up 0.834). 전방 0.11/자기진영 0.67 — 판다이크와 거의 동형의 후방 정박 분포. 25/26 수비액션 6.9→8.6/90 증가(obs#77)로 전방 수비 실패 부하를 함께 짊어진 표본.','RCB 슬롯 커널 정합 0.938 — 이 값이 리버풀 RCB 대체자 영입의 상한 기준선 역할. 약점: 평가 대상으로서의 실효성 자체가 이탈로 소멸했을 가능성 — 스쿼드 잔류 여부부터 데이터 정합 확인 필요.','v_player_profile 0행(8/9 친선 미출전 — 이탈 기재와 정합). 25/26 실측(prescriptions measured): 6경기 평균 6.88, 중심(66.2,34.5). 백분위 산출 불가.','MEDIUM — (교차 투영 — 실측 아님) cb_bpd 요구 자체는 정합이나 빌라의 ''동시 Aggressive 기각''(obs#13) 방침상 포커스 조정 전제. 이적 상태 미확정이라 실전 투영 의미 제한.','HIGH — (교차 투영 — 실측 아님) 알론소 백3 전원 cb_bpd/Aggressive 처방과 역할·포커스 완전 일치. 단 레알 이적이 사실이면 무의미한 투영.','HIGH(커널 기준) — ⚠️ 체제 실측 아님 + 이탈 기재. CB 전진 맨마킹(obs#68·#69) 문법에 Aggressive 커널이 정합하나, obs#69가 명시한 ''코나테 레알 자유이적''이 맞다면 이라올라는 이 프로필을 쓸 수 없다 — 바로 그 공백이 26/27 RCB 영입 과제(RCB·RM·LB 주인 미정, 처방 부재)의 핵심.','squad_entries(r3, lh=OWNED — 불일치) · prescriptions#measured(RCB, n=6, 이탈 기재) · obs#69·#77·#120 · manager_profiles r2/r3','LOW-MEDIUM — 커널 값은 확정적이나 소속 상태가 테이블 간 상충(squad_entries OWNED vs prescriptions·obs#69 이탈). 서술은 이탈 기재 쪽(실측>서사 원칙상 obs 근거 우선)을 병기.','2026-08-11');
INSERT INTO player_evaluations VALUES(36,3,46,'B+ — 미드필더의 RB 전용 기용이라는 희귀 실측 사례(⭐ 표기). 25/26 RB 6경기 평균 7.05, fb_wingback/Support 0.843(신커널), RDM dm_dlp/Roaming 0.800 병립 — 미드필드 드리프트 서술을 실측이 지지. 단 전방 0.26/자기진영 0.39로 구스토(0.34/0.44)·캐시(0.33/0.47)보다 공격 관여가 낮아 3티어의 ''트렌트급'' 서술은 실측이 기각.','인버티드/하이브리드 RB — 풀백 자리에서 중앙 미드필드 지대로 드리프트하는 분포(RB 0.843과 RDM 0.800이 근접 병립). 오버래핑 크로서형이 아니라 안쪽 연결형.','RB와 RDM 두 슬롯을 한 몸으로 커버하는 위치 다능성 — 인버티드 축 참고 표본으로 지정됨. 약점: 전방 질량이 낮아 공격 기여 상한이 제한적(''트렌트형은 전방 질량이 높아야 함'' — 실측 판정), 정통 윙백 폭 제공 능력 미검증.','v_player_profile 0행(8/9 친선 미출전) — 백분위 산출 불가. 25/26 실측(prescriptions measured): RB 6경기 평균 7.05, 중심(77.6,46.4).','MEDIUM-HIGH — (교차 투영 — 실측 아님) 에메리 C2는 RB 잔류형(fb_wingback/Balanced — 캐시 축)을 요구하는데 존스의 실측이 정확히 잔류·연결형 fb_wingback/Support 0.843이다. 낮은 전방 질량이 여기서는 결함이 아니라 요건.','LOW-MEDIUM — (교차 투영 — 실측 아님) 알론소 윙백은 ''크로서가 아니라 득점자''로 폭을 독점(obs#46)하는 전진형 — 존스의 낮은 전방 질량(0.26)과 정면 상충. 반면 하이브리드 RDM(리스 제임스 축, dm_dlp) 투영이라면 RDM 0.800이 근거가 되나 실측은 RB 슬롯 표본.','MEDIUM — ⚠️ 체제 실측 아님. 이라올라 풀백은 낮고 빠른 얼리크로스의 크로서(obs#67, 케르케즈 본머스 실측 근거) — 존스의 인버티드 분포와 문법이 다르다. 다만 상대 풀백 인버트 시 중앙 미드가 따라 올라가는 맨마킹 체계(obs#68)에서 위치 다능성은 자산. 26/27 RB 주인 미정 슬롯의 내부 후보라는 지위 자체는 유효.','squad_entries(r3) · prescriptions#measured(RB, n=6, ⭐) · obs#67·#68·#120 · manager_profiles r1/r2/r3','MEDIUM — RB 표본 6경기는 성립하나 전임 체제 것이고, 본직(미드필드) 실측은 이 체제 표본에 없음.','2026-08-11');
INSERT INTO player_evaluations VALUES(37,3,47,'B− — 25/26 LB 실측 2경기 평균 6.15로 표본 심각 부족(부상으로 3~5월 결장, n<6 명기), fb_att_wb/Support 0.799. 등급은 리버풀 표본이 아니라 본머스 24/25 이라올라 체제 간접 실측(obs#67: 오픈플레이 기회창출 15로 리그 7위, 크로스 37로 6위)이 지탱한다. 로버트슨 토트넘 이적으로 26/27 LB 1선발 유력이나 표본 재수집이 선결 과제.','전진형 공격 윙백(fb_att_wb/Support 0.799, 차2 fb_wingback/Balanced 0.700). 본머스 시절 프로필은 낮고 빠른 얼리크로스 반복 공급자 — 이라올라의 리허설된 패턴의 실행자였다(obs#67).','이라올라 축구를 본머스에서 직접 소화한 스쿼드 유일 자원(obs#76의 본머스 유출 명단 당사자) — 전술 이식의 살아있는 매개. 약점: 리버풀에서의 실측이 2경기뿐이고 그 평균(6.15)도 낮다. 부상 이력(3~5월 결장)이 고주행 체제(총주행 리그 1위 팀 — obs#73)에서 재발 리스크.','v_player_profile 0행(8/9 친선 미출전) — 백분위 산출 불가. 25/26 실측(prescriptions measured): LB 2경기 평균 6.15(표본 심각 부족), 중심(17.7,42.6).','MEDIUM — (교차 투영 — 실측 아님) 에메리 C2 좌측은 전진 담당(LB fb_att_wb/Support — 디뉴 축)이라 역할 문자열은 정확히 일치. 단 리버풀 실측 n=2로 판단 재료 부족.','MEDIUM — (교차 투영 — 실측 아님) 알론소 좌 윙백은 인선 공백 슬롯(r2 formation)이고 요구는 ''폭 독점 + 득점자''(obs#46) — 크로서형인 케르케즈와 득점 요건이 어긋난다. 폭 공급 축만 부분 정합.','HIGH — ⚠️ 리버풀 체제 실측 아님(이라올라 리버풀 공식전 0경기). 단 본머스 24/25가 이라올라 본인 체제 실측이고 거기서 풀백-크로서 패턴의 핵심 수치(기회창출 7위·크로스 6위 — obs#67)를 만든 당사자다. 세 감독 핏 중 유일하게 감독 본인 체제의 과거 실측이 존재 — 다만 리버풀 이식 후 재현은 8/23 개막 후 검증 대상.','squad_entries(r3) · prescriptions#measured(LB, n=2 — 표본 심각 부족) · obs#67·#76 · manager_profiles r3','MEDIUM — 이라올라 핏 근거는 본머스 실측 기반으로 상대적으로 강하나, 리버풀 자체 표본은 n=2로 매우 약함.','2026-08-11');
INSERT INTO player_evaluations VALUES(38,3,48,'B — 25/26 RB 실측 4경기 평균 6.42(표본 부족, n<6 명기), 신커널 fb_att_wb/Support 0.867(차2 Attack 0.845 — Δ0.022는 EA 노이즈). 구커널 산출에선 fb_inverted/Attack 0.905·RM 0.875로 ''풀백이 아니라 사실상 우측 공격 인원'' 판정 — 전방 0.54/자기진영 0.28로 존스의 정반대 분포. 같은 RB 슬롯에 두 유형이 공존한다는 실측 결론.','극단적 전진형 우측 자원 — RB 라벨이지만 질량이 윙어 지대에 쏠린다(전방 0.54). regime3 traits 축도 ''인버티드 RB(프림퐁 fb_inverted 성향 실측)''로 기록. 8/9 모나코 친선에서도 RB 75분 소화.','우측에서 RB~RM 대역을 하나로 잇는 공격 전개력 — 살라 이탈 기재 후 우측 공격 질량의 내부 대안이기도 하다. 약점: 자기진영 질량 0.28로 수비 국면 잔류 신뢰도가 실측상 낮음 — 뒷공간 노출형. 표본 4경기로 확정 판단 불가.','8/9 모나코 친선 1경기: RB 75분 평점 6.10(3팀 풀 백분위 0% — n=1, 의미 제한), KP 1(백분위 44%), 태클·인터셉트 0(실제 0). 25/26 실측(prescriptions measured): 4경기 평균 6.42.','LOW-MEDIUM — (교차 투영 — 실측 아님) 에메리 RB는 잔류형(fb_wingback/Balanced, C2 제약 — 풀백은 한 명씩만 전진)이라 프림퐁의 전진 일변 분포와 상충. 우측 와이드(RM)로 쓴다면 뱅크 복귀형(wm_widemid/Support) 요구가 다시 걸림돌.','HIGH — (교차 투영 — 실측 아님) 알론소 윙백은 ''크로서가 아니라 득점자''로 폭을 독점(obs#46) — 전방 질량 0.54의 전진형 윙백은 이 문법의 원형에 가깝다. 레버쿠젠 시절 알론소 아래 뛴 이력도 있으나 본 DB에 그 실측은 없음.','MEDIUM-HIGH — ⚠️ 체제 실측 아님. regime3 implementation이 ''프림퐁 인버티드 성향은 fb_att_wb로 근사''로 잠정 배치(confidence LOW). 풀백-크로서 문법(obs#67)과 전진성은 정합하나, 맨마킹 체계의 잔류 규율(잔여수비가 엔진 — obs#72) 대비 자기진영 질량 0.28이 리스크. 26/27 RB 주인 미정 — 존스와 유형 경합.','squad_entries(r3) · prescriptions#measured(RB, n=4 — 표본 부족) · v_player_profile(n=1) · obs#67·#72·#120 · manager_profiles r1/r2/r3','MEDIUM — 신·구 커널 값이 유형 서술(전진형)에서는 수렴하나 역할 라벨이 갈렸고(fb_inverted vs fb_att_wb), 표본 4경기.','2026-08-11');
INSERT INTO player_evaluations VALUES(39,3,49,'B — 25/26 LDM 실측 6경기 평균 6.77, dm_dlp/Roaming 0.689(신커널 — 피벗 3인 중 최저 적합, 차2 dm_holding/Roaming 0.525). LDM 0.782 > RDM 0.677로 중앙 피벗 판정, 전방 0.38/자기진영 0.38의 대칭형. 8/9 모나코 친선에서 7.3(어시스트 1)으로 스쿼드 내 상위 퍼포먼스.','박스-투-박스 대칭형 피벗 — 전후방 질량이 정확히 균형(0.38/0.38). ⚠️ obs#120 ⓑ: 피벗 3인(흐라벤베르흐·소보슬라이·맥알리스터)이 전부 dm_dlp/Roaming으로 나와 움직임만으로는 기능 분화가 안 보이며, 리버풀 기능축 실측(appearances·player_match_positions)이 0행이라 이 분화를 가릴 수단이 없다 — 본 평가의 역할 서술은 이 한계 안에서 읽어야 한다.','전천후 커버 범위와 운반 — 대칭 분포가 시사하는 왕복 능력. 친선이지만 KP 2·태클 1·인터셉트 2·어시스트 1의 전방위 기여. 약점: 어느 역할 커널에도 강하게 맞지 않음(최고 0.689) — 특화 부재가 곧 프로필. FC26 스탯 미수집.','8/9 모나코 친선: 59분 평점 7.30(3팀 풀 백분위 79%), KP 2(76%), 인터셉트 2(89%) — 단 n=1로 서열 의미 제한. 25/26 실측(prescriptions measured): LDM 6경기 평균 6.77, 중심(52.9,48.6).','MEDIUM — (교차 투영 — 실측 아님) 에메리 더블 피벗 처방은 dm_holding(Roaming/Defend 분담) — 흐라벤베르흐의 차2가 dm_holding/Roaming(0.525)이나 값이 낮아 정합 주장 불가. 대칭형 왕복은 뱅크 복귀 규율과는 무난.','MEDIUM-HIGH — (교차 투영 — 실측 아님) 알론소 하강 피벗(카이세도 dm_dlp/Roaming — r2 implementation)과 역할·포커스 문자열이 일치. 단 박스 미드필드 중앙 볼 상실 리스크(r2 rest_defense)상 기술 규율 요구가 극단적으로 높다는 유보 조건 동반.','MEDIUM-HIGH — ⚠️ 체제 실측 아님. 이라올라는 중앙 미드가 상대 박스까지 따라 올라가는 맨마킹(obs#68·#69)과 리그 1위 주행량(obs#73)을 요구 — 대칭 왕복형 분포가 이 요구와 방향은 맞다. 단 기능축 0행이라 피벗 내 역할 배분(누가 잔류하는지)은 판정 불가 — 개막 실측 대기.','squad_entries(r3) · prescriptions#measured(LDM, n=6) · v_player_profile(n=1) · obs#68·#69·#73·#120ⓑ · manager_profiles r1/r2/r3','MEDIUM — 실측 6경기는 성립하나 전임 체제 표본 + 기능축 미수집(obs#120ⓑ)으로 역할 분화 판정 불가.','2026-08-11');
INSERT INTO player_evaluations VALUES(40,3,50,'B — 25/26 LDM 실측 5경기 평균 6.64(n<6, 표본 부족 명기), dm_dlp/Roaming 0.890(신커널 — 피벗 3인 중 최고 적합, 차2 Build-Up 0.690). LDM 0.909 > RDM 0.639(구커널 병기)로 좌측 피벗 특화. ⚠️ 흐라벤베르흐와 동일 슬롯·동일 역할 최적 — 더블 피벗 두 축이 실측상 분화되지 않아 슬롯 배분은 별도 판단 필요(prescriptions 명기).','딥라잉 플레이메이커 — 커널 정합 0.890은 피벗 중 뚜렷한 최고(흐라벤베르흐 0.689·소보슬라이 0.674와의 Δ0.2는 노이즈 범위 밖). 전방 0.33/자기진영 0.37로 후방 연결 중심. obs#120 ⓑ의 기능축 0행 한계는 동일 적용 — 움직임 커널만으로는 ''무엇을 했는지''(배급/탈압박/수비)를 못 가린다.','피벗 커널 정합 팀 내 최고(0.890) — dlp 역할 배치 시 구조 리스크가 가장 낮은 미드필더. 약점: 실측 평균 6.64는 피벗 3인 중 최저이고 표본도 5경기 — 정합도와 산출이 어긋나는 표본. 8/9 친선 미출전으로 최신 폼 데이터 없음.','v_player_profile 0행(8/9 친선 미출전) — 백분위 산출 불가. 25/26 실측(prescriptions measured): LDM 5경기 평균 6.64(표본 부족), 중심(47.1,49.2).','MEDIUM — (교차 투영 — 실측 아님) 에메리 피벗 처방은 dm_holding 계열 — dlp 특화형과 역할 문자열 불일치. 자유 10번(cam_playmaker/Roaming — 부엔디아·맥긴 축) 투영이 대안이나 실측 표본은 DM 슬롯 것.','HIGH — (교차 투영 — 실측 아님) 알론소 하강 피벗 카이세도 처방이 정확히 dm_dlp/Roaming — 역할·포커스 완전 일치에 정합도 0.890. 백라인 옆으로 내려와 압박을 유인하는 빌드업 축의 커널 원형. 단 박스 미드필드의 볼 상실 리스크(r2 rest_defense) 유보 동일.','MEDIUM — ⚠️ 체제 실측 아님. 이라올라는 시퀀스당 패스 2.98의 비점유 다이렉트 팀(obs#66) — 점유형 딥라잉 배급자의 가치가 구조적으로 줄어드는 문법이다. 중앙 미드 전진 맨마킹(obs#68) 요구 대비 전방 질량 0.33도 낮은 편. 기능축 0행이라 확정 불가 — 개막 실측이 판정.','squad_entries(r3) · prescriptions#measured(LDM, n=5 — 표본 부족) · obs#66·#68·#120ⓑ · manager_profiles r1/r2/r3','MEDIUM — 커널 값 확정적(0.890), 산출(6.64)과의 괴리 및 기능축 미수집이 유보 사유.','2026-08-11');
INSERT INTO player_evaluations VALUES(41,3,51,'B+ — 스쿼드 유일의 다중 슬롯 순회 실측(RM/RDM/CAM 36경기, 평균 7.02 — 표본 최대). 세 라벨 중 실측 최적은 RDM: 구커널 dm_dlp/Roaming 0.812 > RM 0.730 > CAM 0.673, 신커널 재산출은 dm_dlp/Roaming 0.674(차2 dm_boxcrasher/Balanced 0.569 — obs#120). 전방 0.49/자기진영 0.23의 전진 편향 피벗.','전진형 하이브리드 — DM 라벨이 최적이지만 질량 절반이 전방(0.49)에 있는 박스 침입 성향(신커널 차2가 boxcrasher인 것과 정합). 8/9 모나코 친선도 RDM 76분, KP 3. ⚠️ obs#120 ⓑ: 피벗 3인 전부 dm_dlp/Roaming 판정 + 기능축 실측 0행 — 맥알리스터·흐라벤베르흐와의 기능 분화를 데이터로 가릴 수 없다.','위치 다능성(RM/RDM/CAM 3슬롯 실전 순회)과 스쿼드 최대 표본(36경기 7.02)의 안정 산출. 친선 KP 3은 3팀 풀 백분위 94%(단 n=1). 약점: 신커널 정합 0.674로 어느 커널에도 강하게 맞지 않음 — 다능성의 대가. 구(0.812)·신(0.674) 값 괴리가 커서 역할 확신도 자체가 낮은 상태.','8/9 모나코 친선: RDM 76분 평점 6.60(백분위 16%), KP 3(94%) — n=1 유보. 25/26 실측(prescriptions measured): 다중 슬롯 36경기 평균 7.02, 중심(59.8,57.0).','MEDIUM-HIGH — (교차 투영 — 실측 아님) 에메리 자유 10번(cam_playmaker/Roaming) 또는 전진 피벗 투영 모두 가능 — 다능성이 에메리의 상황 프리셋 체계(리드 시 딥블록 등)와 궁합. 단 우측 와이드 기용이라면 뱅크 복귀(wm_widemid/Support) 규율이 전진 편향과 상충.','MEDIUM — (교차 투영 — 실측 아님) 하이브리드 RDM 창조 축(리스 제임스 dm_dlp/Build-Up — r2)과 지대는 겹치나, 소보슬라이의 전방 질량 0.49는 하강 빌드업보다 2×10번 지대에 가깝다 — 어느 쪽에도 완전 정합은 아님.','HIGH — ⚠️ 체제 실측 아님. 이라올라 4-2-3-1에서 중앙 미드가 상대 박스까지 진입하는 문법(obs#68·#69 ''Lewis Cook을 상대 박스에서 보게 된다'')의 커널 대응이 정확히 전진형 피벗/boxcrasher 성향이다. 리그 1위 주행 체제(obs#73)에 다능성·활동량 프로필이 부합. 단 판정은 개막 실측 후.','squad_entries(r3) · prescriptions#measured(RDM, 다중슬롯 36경기, ⭐) · v_player_profile(n=1) · obs#68·#69·#73·#120 · manager_profiles r1/r2/r3','MEDIUM-HIGH — 표본은 팀 내 최대(36경기)이나 전임 체제 것이고, 신·구 커널 값 괴리(0.812→0.674)가 미해소.','2026-08-11');
INSERT INTO player_evaluations VALUES(42,3,52,'A− — 25/26 CAM 실측 5경기 평균 7.00(n<6, 표본 부족 명기), cam_halfwinger/Balanced 0.785(차2 classic10/Versatile 0.711). prescriptions 명기: ''£100m 영입 대비 부진 시즌이라는 서사와 달리 평점은 필드 상위'' — 실측>서사 원칙의 사례. 8/9 모나코 친선 평점 8.60(1골)은 이번 조회 3팀 풀 최고값(백분위 98%, 단 n=1).','하프윙어형 10번 — 중앙 라벨이되 측면 하프스페이스로 흘러나오는 분포(halfwinger 0.785 > classic10 0.711, RM 0.687). 전방 0.54/자기진영 0.19의 공격 전담형. 특기: 8/9 친선에서 LDM으로 선발돼 8.6을 찍었다 — 슬롯 하향 기용 실험의 단일 표본.','최종 3분의 1 창조의 중심축 — 친선 1경기에서 골·KP 1·태클 2·지상경합 3승의 전방위 관여. 약점: 자기진영 질량 0.19로 수비 국면 기여가 실측상 얇고, FC26 스탯·PlayStyles 미수집이라 인게임 능력 축은 공백. 표본 5경기.','8/9 모나코 친선: LDM 59분 평점 8.60(3팀 풀 57행 대비 백분위 98% — n=1 유보), 1골, 태클 2(72%). 25/26 실측(prescriptions measured): CAM 5경기 평균 7.00, 중심(54.1,58.7).','HIGH — (교차 투영 — 실측 아님) 에메리 자유 10번 슬롯(cam_playmaker/Roaming 또는 cam_halfwinger — r1 implementation ⑸에 halfwinger가 만잠비 축으로 명시)과 실측 최적 역할이 일치. 로밍 자유를 주는 문법이 비르츠의 하프스페이스 유동과 정합.','HIGH — (교차 투영이지만 예외적 근거: 레버쿠젠 시절 알론소 본인 체제의 서사 실측 존재) obs#45: 샤카·팔라시오스의 third-man 콤비네이션의 종착지가 비르츠. obs#48: 2×10번 중 ''로머/최종 창조자'' 축이 비르츠로 명시 — 세 감독 핏 중 감독-선수 실제 협업 기록이 있는 유일 조합. 단 첼시 이식 검증 전(r2 confidence MEDIUM)이며 25/26 리버풀 표본은 알론소 것이 아니다.','MEDIUM-HIGH — ⚠️ 체제 실측 아님. regime3 traits가 ''비르츠 하프윙어 10번''으로 잠정 배치(confidence LOW). 수직 전환 체제(전진 속도 1.95m/s 리그 최속 — obs#66)에서 전환 순간의 최종 패스 자원으로 투영되나, 파이널서드 탈취→즉시 슛 문법(r3 pressing)에 필요한 압박 관여는 자기진영 질량 0.19가 물음표 — 개막 실측 대기.','squad_entries(r3) · prescriptions#measured(CAM, n=5 — 표본 부족) · v_player_profile(n=1, 8.6) · obs#45·#48·#66 · manager_profiles r1/r2/r3','MEDIUM-HIGH — 커널 값 확정, 알론소 축은 레버쿠젠 서사 실측으로 보강. 리버풀 표본 5경기 + FC26 스탯 공백이 유보 사유.','2026-08-11');
INSERT INTO player_evaluations VALUES(43,3,53,'B− — 25/26 LM 실측 6경기 평균 6.52(피벗 포함 필드 실측 중 최저권), 신커널 wm_insidefwd/Balanced 0.675(차2 Attack 0.652 — Δ0.023 노이즈). 구커널 병기값이 문제의 핵심: LM 0.648·CAM 0.686·ST 0.579 — 세 슬롯 모두 0.7 미만으로 ''어디에도 강하게 맞지 않는다''(prescriptions 명기, LM↔ST 겸업의 대가).','인사이드 포워드형 — 좌측 라벨이되 중앙·전방으로 질량이 쏠린다(전방 0.59/자기진영 0.13, 스쿼드 최전방권 분포). LM과 ST를 오간 겸업 이력이 커널 응집도를 희석시킨 표본.','전방 질량 0.59의 박스 근접성과 좌측~중앙 다능성. 친선 KP 2(백분위 76%, n=1). 약점: 특화 슬롯 부재가 정량으로 확인된 유일 사례(전 슬롯 0.7 미만) — 로테이션 자원 이상의 지위를 실측이 지지하지 않음. 자기진영 0.13으로 수비 관여 최저권.','8/9 모나코 친선: LM 59분 평점 7.00(3팀 풀 백분위 53%), KP 2(76%) — n=1 유보. 25/26 실측(prescriptions measured): LM 6경기 평균 6.52, 중심(42.5,63.6).','LOW-MEDIUM — (교차 투영 — 실측 아님) 에메리 와이드는 뱅크 복귀 수비 규율(wm_widemid/Support 또는 obs#125 winger/Balanced 사다리)을 요구 — 자기진영 질량 0.13과 정면 상충. 인사이드 포워드 기용(obs#124 문법)이라면 가능하나 그 역할 요구 대비 커널 정합이 0.675로 낮다.','MEDIUM — (교차 투영 — 실측 아님) 2×10번 중 안으로 좁히는 축(로저스 wm_insidefwd — r2 implementation)과 역할 문자열이 일치 — 세 투영 중 문법 정합이 가장 낫다. 단 정합도 절대값(0.675)이 낮아 강한 주장 불가.','MEDIUM — ⚠️ 체제 실측 아님. 좌측 인사이드 포워드 지대 자체는 4-2-3-1 셸에 존재하나, 수비 4-4-2 복귀와 맨마킹 인계(obs#68)가 요구하는 수비 관여를 자기진영 0.13이 지지하지 않는다. 파이널서드 탈취→즉시 슛 국면의 마무리 자원 투영은 가능 — 개막 실측 대기.','squad_entries(r3) · prescriptions#measured(LM, n=6) · v_player_profile(n=1) · obs#68·#124·#125 · manager_profiles r1/r2/r3','MEDIUM — 표본 6경기 성립, ''전 슬롯 0.7 미만'' 판정은 구커널 값이라 신커널 기준 재검 여지.','2026-08-11');
INSERT INTO player_evaluations VALUES(44,3,54,'A — 25/26 RM 실측 5경기 평균 7.56으로 리버풀 필드 최고(n<6, 표본 부족 명기). 신커널 wm_winger/Attack 0.910(obs#120 — 구커널의 wm_insidefwd 0.961은 폐기값, 신기준 insidefwd는 0.515). 침투 서명 전방 0.77/자기진영 0.06은 이 프로젝트 전 측정 후보 중 최상위권. ⚠️ 소속 상태 데이터 불일치: prescriptions는 ''2026-07-01 FA로 이탈 — obs#38 브리프의 실측 원형(archetype)으로 보존''이라 기재했는데 squad_entries(r3)에는 lh=OWNED로 남아 있다.','정통 터치라인 윙어의 침투형(wm_winger/Attack) — obs#100·#120이 독립 재현한 판정: ''뒷공간 반복 침투 빠른 우측 윙어''의 커널은 insidefwd가 아니라 winger다. 자기진영 질량 0.06은 수비 관여 실측 최저 — 순수 공격 전담.','우측 뒷공간 침투의 실측 상한 기준선 — 빌라 우측 후보 평가(obs#38 브리프)의 비교 원형으로 보존될 만큼의 서명. 약점: 수비 국면 기여 사실상 0(자기진영 0.06) — 두 줄 수비 체제에서는 구조 비용을 동반. 이탈 기재가 사실이면 평가 실효성 자체가 아카이브용.','v_player_profile 0행(8/9 친선 미출전 — 이탈 기재와 정합) — 백분위 산출 불가. 25/26 실측(prescriptions measured): RM 5경기 평균 7.56, 중심(82.6,71.3).','MEDIUM(커널 기준 HIGH, 구조 기준 LOW) — (교차 투영 — 실측 아님) obs#100 개정 후 에메리 우측 윙어 브리프의 목표 커널이 정확히 wm_winger — 살라 그리드가 그 브리프의 상한 기준선이다. 그러나 에메리 두 줄 4 뱅크 복귀(obs#125의 winger/Balanced 요구)와 자기진영 0.06은 정면 상충 — ''기준선''이지 ''처방 대상''이 아니다.','LOW-MEDIUM — (교차 투영 — 실측 아님) 알론소 3-4-2-1에는 터치라인 윙어 슬롯이 없다(폭은 윙백 독점 — obs#46). 우측 포켓 10번(팔머 wm_wideplm/Attack 축)은 다른 직무.','MEDIUM-HIGH(커널 기준) — ⚠️ 체제 실측 아님 + 이탈 기재. regime3 traits의 잠정 배치가 ''살라 wm_winger/Attack''이고 수직 전환·패스트브레이크 체제(obs#66: 패스트브레이크 슛 128)와 침투 서명이 정합. 그러나 맨투맨 프레스는 최전방부터의 압박 가담(obs#68 곡선 런)을 요구 — 자기진영 0.06과 상충. 이탈이 사실이면 논의 자체가 소급 불가.','squad_entries(r3, lh=OWNED — 불일치) · prescriptions#measured(RM, n=5, ⭐⭐, 이탈 기재) · obs#38·#66·#68·#100·#120 · manager_profiles r1/r3','LOW-MEDIUM — 커널 값은 obs#100·#120 이중 재현으로 견고하나, 소속 상태가 테이블 간 상충. 실측 5경기 표본 부족.','2026-08-11');
INSERT INTO player_evaluations VALUES(45,1,75,'B+ — 처방 축(더블 피벗 볼위닝) 정면 보강이자 오나나 부상·틸레만스 이탈 공백의 1:1 해법. 역할 정체성 완벽, 슬롯 커널 적합은 중간, 부상 리스크 존재.','볼위닝 앵커(태클·인터셉트·세컨드볼), 190cm 세트피스 빅바디(공중듀얼 62%), 광역 커버로 단독 전환 방어. 온볼 배급 비엘리트, 파울·경고 비용(풀럼 2년 경고 27장).','PL 검증 완료(풀럼 태클 300개 1위 + 토트넘 25/26 중심 기둥 재검증), 에메리 미드블록의 중앙 차단 임무와 기질 일치. 약점: 빌드업 기여 한계(LDM 커널 dm_widehalf/Build-Up .709가 이를 정량화), 네거티브 PS ''부상에 취약함'', 30세(1995년생) 에이징 커브.','transfer_targets 표본(6경기 평균 6.92) 기준 견실하나 스타 레벨 아님 — 잭슨 7.45·아우안 7.18보다 낮지만 DM 평점 기저 감안 시 준수. 그리드 중심(53.7, 44.0) 중앙 저지대 편중이 앵커 임무 수행을 실증.','HIGH — 숙련 dm_holding/Ball-Winning이 에메리 더블 피벗 처방과 정확 일치(DB rationale ''기능축 처방과 정확 일치 — 확정''). 슬롯 fit_sim LDM .709(dm_widehalf/Build-Up)·RDM .738(dm_dlp/Roaming) — 커널 지불은 있으나 카마라 부재 시나리오의 보험 가치가 상회.','(교차 투영 — 실측 아님) MEDIUM — 백3 빌드업·윙백 폭 독점 구조(regime 2)에서 싱글/더블 6의 수비 반경은 부합하나, 하프스페이스 2×10번을 받치는 6번에게 요구되는 전진 배급이 그의 최약점.','(교차 투영 — 실측 아님) MEDIUM-HIGH — 고강도 압박·수직 전환(regime 3)에 태클·회수 기질은 부합, 파이널서드 탈취 지향의 전면 맨투맨 전환 시 광역 커버가 자산. 단 탈취 후 즉시 슛/전진 연결의 온볼 속도는 캐비앗.','Total Football Analysis(25/26 토트넘 스카우트 리포트) · BBC Sport · DB transfer_targets#91·92','서사 소스(3티어급) + DB 실측 6경기 — 시즌 전수 아님. 이적 구조(임대+옵션 vs 완전 €25~30m) 교착은 DB 08-09 기준.','2026-08-11');
INSERT INTO player_evaluations VALUES(46,1,76,'A- — 표본 평점 최고(7.45)·fit 최고권(.752)·나이(2001년생) 모두 4후보 중 상위. 리스크는 £60m+ 클럽레코드 이적료와 마무리 기복.','딥존 발동형 9번 — 등지고 레이오프, 파워 스트라이드 가교, 압박 개시·하이 리커버리. 클래식 박스 포처 아님(바이에른 공식 프로필). DB 확인 PS 게임체인저·테크니컬.','링크·침투 이중 위협, 수비 기여(백업으로도 콤파니가 공개 옹호·잔류 희망), 분데스 우승 스쿼드 경험. 약점: 마무리 안정성(바이에른 첫 6경기 무득점 — ''골만 오면 된다''는 콤파니 발언이 역설적 증거), AFCON 결장 공백(세네갈), 첼시 복귀 후 서열(조앙 페드로·델랍·웰벡 적체)이 오히려 매물화 호재.','transfer_targets 표본(6경기 평균 7.45) 기준 4후보 중 최고 — 9골 4도움 후반기 회복 서사와 정합. map25 전진 질량 + Support 하강 링크가 st_advanced/Support .752를 실증.','HIGH — fit_sim .752, opt=fit 일치(st_advanced/Support). 에메리-비야레알 인연 + 왓킨스와 로테이션/공존 모두 가능한 프로필. 하강 링크가 자유 10번(부엔디아·로저스류)과의 연계 축을 추가.','(교차 투영 — 실측 아님) HIGH — 3-4-2-1 원톱은 2×10번을 위해 등지고 내주는 링크형 9번을 요구 — 잭슨의 레이오프·채널 침투 이중성이 구조 요구와 부합.','(교차 투영 — 실측 아님) HIGH — 압박 개시·하이 리커버리 기질이 하이브리드 프레스의 1선 트리거 역할과 정확 부합. 탈취 후 즉시 슛 국면에서 마무리 기복이 유일 감점.','FC Bayern 공식 프로필 · Bavarian Football Works · Goal · DB transfer_targets#123','서사 소스(3티어급 + 클럽 1차) + DB 실측 6경기(후반기 편중 가능). 딜 상태는 DB 08-09 기준 HIGH-정체(임대 경로 봉쇄·완전이적만 잔존).','2026-08-11');
INSERT INTO player_evaluations VALUES(47,1,77,'B — 재능·평점(7.18)·나이(2004년생) 대비 구조 적합이 발목: 해방 윙어 풋프린트인데 빌라 우측은 뱅크 칸. 성사 확률도 셀링클럽 블록으로 4후보 중 최저.','왼발 인버티드 RW — 드리블 Very Strong·공중듀얼 Strong(WhoScored), 오프더볼 성실·전술 성숙(''더 강한 하비 엘리엇''). 크로스·규율(경고 3·퇴장 1) 약점, 통산 64경기 5골로 득점 전환 미완.','양 윙 소화 다재 + 압박 가담 — 뱅크 복귀 임무 학습 가능성은 서사가 지지. 약점: CAM 겸용 주장은 실측 기각(.674), RM 실기용 시 wm_widemid/Support .734 지불, PL 무경험 + 브라질發 적응 리스크, FC26 미존재(게임 재현 불가 — 커스텀 생성 필요).','transfer_targets 표본(6경기 평균 7.18, 최고 8.4) 기준 우측·전진 편향(중심 77.2, 59.4) 뚜렷 — RM 커널 .812는 하지무사·은디아예와 동급이나 W군 w_wideplm/Build-Up .870이 진짜 정체(해방 윙어).','MEDIUM — fit_sim .812(wm_winger/Balanced)는 수치상 4후보 중 2위지만, 에메리 우측이 요구하는 4-4-2 뱅크 복귀(wm_widemid/Support)로 재면 .734로 하락 — DB 판정 ''해방 사이드용 자원, 현 스쿼드 구조와 어긋남'' 유지. 로저스 대체 창조 자원이라는 영입 서사와 실측 풋프린트가 반만 겹친다.','(교차 투영 — 실측 아님) HIGH — 하프스페이스 2×10번 구조가 그의 최적 서식지: 인버티드 컷인 + 좁은 지역 콤비네이션 + CAM 미달이어도 10번 슬롯은 윙백이 폭을 대신 지므로 실측 우측 편향과 충돌이 적다.','(교차 투영 — 실측 아님) MEDIUM-HIGH — 압박 성실성·수직 드리블은 부합하나 이라올라 윙어에게 요구되는 터치라인 고정·크로스 볼륨이 그의 약점(크로스 weak)과 정면 충돌.','Rousing The Kop(2026-02 스카우트 리포트) · WhoScored · FotMob · DB transfer_targets#139','서사 소스(3티어급) + DB 실측 6경기. 성사 리스크 별도: 팔메이라스 협상 거부·€45m+ 요구·바이아웃 €100m + 리버풀 우선매수권 보도(2026-02, 3티어) — DB 08-09 MEDIUM-HIGH 판정과 병존.','2026-08-11');
INSERT INTO player_evaluations VALUES(48,1,78,'A- — 4후보 중 구조 적합 최고(.949)·성사 조건 최선(아틀레티코 매도 동기 구조적)·나이(2002년생) 균형. 천장은 낮다 — 스타가 아니라 정확한 부품.','전진형 LB — 오버랩·크로스 볼륨(톱5리그 LWB progressive passes 81퍼센타일), 공중듀얼 강점(187cm), 백4/윙백 겸용. 1대1 수비 다듬기 필요, 공격 마무리 사실상 0(시즌 xG 0.36).','가스페리니 고강도 3백 윙백 + 시메오네 백4 모두 검증된 전술 이식성, 에메리가 원하는 LB 피지컬 프로필(The Athletic 확인). 약점: 득점 위협 부재, 평점 6.77(수비수 기저 감안해도 평범), PL 무경험.','transfer_targets 표본(6경기 평균 6.77) 기준 평점은 평범하나 그리드가 본질 — 좌측 레인 수직 분포·X 공격행 좌터치라인, fb_att_wb/Support .949(Δ.214 단독 1위)로 에스투피냔(.946)의 사실상 복제 프로필.','HIGH — fit_sim .949는 전체 후보 통틀어 최고. 에메리 C2 비대칭(LB 전진 fb_att_wb/Support vs RB 잔류)의 좌측 축과 정확 일치 — 디뉴(→PSG) 공백의 1:1 대체이자 에스투피냔 딜 정체의 헤지. FC26 존재(77/83)로 게임 재현도 즉시 가능.','(교차 투영 — 실측 아님) HIGH — regime 2의 ''좌 윙백 인선 공백''에 정확히 꽂히는 프로필: 윙백 폭 독점 구조에서 크로스·전진패스형 LWB는 요구 사양 그대로. 가스페리니 3백 이력이 이식성 방증.','(교차 투영 — 실측 아님) MEDIUM — 오버랩 동력은 부합하나 이라올라 풀백에 요구되는 전면 맨투맨 1대1 수비가 그의 지목된 약점 — 측면 압축 구조에서 노출 위험.','Total Football Analysis(25/26 아틀레티코 스카우트 리포트) · Into the Calderon · The Athletic(Tanswell, DB 경유) · DB transfer_targets#141','서사 소스(3티어급, 1티어 관심 확인은 DB 기록 경유) + DB 실측 6경기(5월 편중). 딜 상태 DB 08-09 기준 HIGH(오퍼 제출·선수 검토 중).','2026-08-11');
